'use strict';
// Sign-in controller for the JWT auth flow (administrator-approved deviation).
//
// On load: GET /api/auth/bootstrap/status.
//   - canCreateSuperadmin  -> show the create-superadmin form
//                             (POST /api/auth/bootstrap/superadmin, password >=12)
//   - otherwise            -> show the email/password login form
//                             (POST /api/auth/login)
// A login that returns 403 PASSWORD_SETUP_REQUIRED swaps in a set-password form
// (POST /api/auth/setup/password, then re-login).
//
// On success the server sets httpOnly cookies (access + refresh). The access
// token also comes back in the JSON body; the app keeps it in memory, but for
// navigation we simply send the browser to `/` — the server-side gate
// (rule-q50) validates the access-token cookie and serves the shell.

const $ = (id) => document.getElementById(id);

// One-time sign-in link mode: /login#link=<token> (admin-issued). The token is
// the credential; the setup form collects the new password and
// POST /auth/link/complete signs the user in. Held in memory only.
let linkToken = null;

// Whether the create-first-administrator door is still open, so the "sign in
// instead" link knows whether to offer a way back.
let canBootstrap = false;

async function apiJson(path, opts) {
  const res = await fetch('/api' + path, {
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    ...opts,
  });
  let body = {};
  try {
    body = await res.json();
  } catch (_e) {
    body = {};
  }
  return { res, body };
}

function show(which) {
  ['login-loading', 'form-bootstrap', 'form-login', 'form-setup'].forEach((id) => {
    const el = $(id);
    if (el) el.hidden = id !== which;
  });
}

function setMsg(id, text) {
  const el = $(id);
  if (el) el.textContent = text || '';
}

// A successful sign-in issues cookies server-side; hand off to the gated shell.
function goToApp() {
  window.location.assign('/');
}

/* ---------- create superadmin ---------- */
function wireBootstrap() {
  $('form-bootstrap').addEventListener('submit', async (e) => {
    e.preventDefault();
    setMsg('bootstrap-msg', '');
    const email = $('bootstrap-email').value.trim();
    const password = $('bootstrap-password').value;
    if (password.length < 12) {
      setMsg('bootstrap-msg', 'Password must be at least 12 characters.');
      return;
    }
    const { res, body } = await apiJson('/auth/bootstrap/superadmin', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    if (res.ok) {
      goToApp();
      return;
    }
    setMsg('bootstrap-msg', body.message || body.error || 'Could not create administrator.');
  });
}

/* ---------- normal login ---------- */
function wireLogin() {
  $('form-login').addEventListener('submit', async (e) => {
    e.preventDefault();
    setMsg('login-msg', '');
    const email = $('login-email').value.trim();
    const password = $('login-password').value;
    const { res, body } = await apiJson('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    if (res.ok) {
      goToApp();
      return;
    }
    // First-time password setup required — swap to the setup form.
    if (res.status === 403 && body.error === 'PASSWORD_SETUP_REQUIRED') {
      $('setup-email').value = email;
      $('setup-password').value = '';
      setMsg('setup-msg', '');
      show('form-setup');
      $('setup-password').focus();
      return;
    }
    setMsg('login-msg', body.message || body.error || 'Sign in failed.');
  });
}

/* ---------- first-time password setup ---------- */
function wireSetup() {
  $('form-setup').addEventListener('submit', async (e) => {
    e.preventDefault();
    setMsg('setup-msg', '');
    const email = $('setup-email').value.trim();
    const password = $('setup-password').value;
    if (password.length < 12) {
      setMsg('setup-msg', 'Password must be at least 12 characters.');
      return;
    }
    // Link mode: the token authorizes the password set + signs in directly.
    if (linkToken) {
      const done = await apiJson('/auth/link/complete', {
        method: 'POST',
        body: JSON.stringify({ token: linkToken, password }),
      });
      if (done.res.ok) {
        goToApp();
        return;
      }
      setMsg('setup-msg', done.body.message || done.body.error || 'This sign-in link is no longer valid \u2014 ask an administrator for a new one.');
      return;
    }
    const setup = await apiJson('/auth/setup/password', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    if (!setup.res.ok) {
      setMsg(
        'setup-msg',
        setup.body.message || setup.body.error || 'Could not set password.',
      );
      return;
    }
    // Password set — sign in with the new credentials.
    const { res, body } = await apiJson('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    if (res.ok) {
      goToApp();
      return;
    }
    setMsg('setup-msg', body.message || body.error || 'Sign in failed after setup.');
  });
}

/* ---------- switching between the two first-run doors ---------- */
// A fresh app shows ONLY "create the first administrator", so any account
// that already exists — a seeded fixture user, an LDAP account, a second
// admin created before this browser ever loaded — is unreachable from the
// UI. These two links make both doors available whenever both apply.
function wireSwitch() {
  const toLogin = $('to-login');
  if (toLogin) toLogin.addEventListener('click', () => {
    setMsg('login-msg', '');
    show('form-login');
    const alt = $('alt-bootstrap');
    if (alt) alt.hidden = !canBootstrap;
    $('login-email').focus();
  });
  const toBootstrap = $('to-bootstrap');
  if (toBootstrap) toBootstrap.addEventListener('click', () => {
    setMsg('bootstrap-msg', '');
    show('form-bootstrap');
    $('bootstrap-email').focus();
  });
}

/* ---------- boot ---------- */
(async function boot() {
  wireBootstrap();
  wireLogin();
  wireSetup();
  wireSwitch();
  // A one-time sign-in link lands here as /login#link=<token>. Validate it
  // (GET status is non-consuming — previews are safe) and open the set-password
  // form with the account's masked email; an invalid/used link falls through to
  // the normal flow with a clear message.
  const linkMatch = (window.location.hash || '').match(/link=([A-Za-z0-9_-]{10,})/);
  if (linkMatch) {
    const probe = await apiJson('/auth/link/status?token=' + encodeURIComponent(linkMatch[1]), { method: 'GET' });
    if (probe.res.ok && probe.body.valid) {
      linkToken = linkMatch[1];
      const emailEl = $('setup-email');
      emailEl.type = 'text';
      emailEl.value = probe.body.email || 'your account';
      $('setup-password').value = '';
      setMsg('setup-msg', '');
      show('form-setup');
      $('setup-password').focus();
      return;
    }
    setMsg('login-msg', 'That sign-in link has expired or was already used \u2014 sign in below, or ask an administrator for a new link.');
  }
  try {
    const { res, body } = await apiJson('/auth/bootstrap/status', { method: 'GET' });
    canBootstrap = !!(res.ok && body.canCreateSuperadmin);
    if (canBootstrap) {
      show('form-bootstrap');
      $('bootstrap-email').focus();
    } else {
      show('form-login');
      $('login-email').focus();
    }
  } catch (_e) {
    // If status can't be fetched, default to the login form.
    show('form-login');
  }
})();

'use strict';
// Front-end RBAC gating — the SINGLE place the browser decides which Connection
// Settings controls an admin may edit. Loaded as a classic <script> before
// app.js (exposes window.Rbac) and also importable by the jsdom interaction
// test (assigns module.exports when running under CommonJS).
//
// Why this exists: the "admin cannot type into Connection Settings" defect came
// from app.js comparing the role against a hard-coded 'admin' literal while
// /api/profile returned the display LABEL "Administrator". The slug values below
// mirror the server's canonical set in src/auth/roles.ts EXACTLY — a build test
// (rbac-shared-consistency.test.ts) asserts they match so the two layers can
// never drift. normalizeRoleSlug() tolerates case and label/slug mixups so
// "Administrator" / "ADMIN" / "admin" all resolve to the same slug.
(function (root) {
  var ROLE_ADMIN = 'admin';
  var ROLE_MANAGER = 'manager';
  var ROLE_VIEWER = 'viewer';
  var ROLE_EXTERNAL = 'external';

  var LABEL_TO_SLUG = {
    administrator: ROLE_ADMIN,
    admin: ROLE_ADMIN,
    manager: ROLE_MANAGER,
    viewer: ROLE_VIEWER,
    external: ROLE_EXTERNAL,
  };

  // Normalise any role value (slug or display label, any case) to a canonical
  // slug; least privilege (viewer) for anything unrecognised.
  function normalizeRoleSlug(value) {
    if (!value) return ROLE_VIEWER;
    var key = String(value).trim().toLowerCase();
    return Object.prototype.hasOwnProperty.call(LABEL_TO_SLUG, key)
      ? LABEL_TO_SLUG[key]
      : ROLE_VIEWER;
  }

  // Admin only may EDIT the connection. Admins + Managers may run the test
  // (rule-q28: Manager view + trigger sync). Viewers are read-only.
  function canEditConnection(role) {
    return normalizeRoleSlug(role) === ROLE_ADMIN;
  }
  function canTestConnection(role) {
    var slug = normalizeRoleSlug(role);
    return slug === ROLE_ADMIN || slug === ROLE_MANAGER;
  }

  // Edit surfaces gated to admins. The write-only client-secret box is NOT in
  // this list: it stays disabled until "Replace" is clicked even for an admin.
  var CONNECTION_EDIT_IDS = [
    'adp-client-id', 'adp-token-url', 'adp-api-base', 'adp-test-path',
    'cert-pem', 'cert-file', 'cert-passphrase', 'key-pem', 'key-file',
    'save-credentials', 'secret-replace', 'save-key', 'upload-cert', 'save-endpoints',
  ];

  // Apply role-based enable/disable to the Connection Settings surfaces of a
  // document. Pure DOM work so it is exercised directly by the jsdom test.
  // (constitution §4 — RBAC is enforced server-side; this is UX only.)
  function applyConnectionRbac(doc, role) {
    var editable = canEditConnection(role);
    CONNECTION_EDIT_IDS.forEach(function (id) {
      var el = doc.getElementById(id);
      if (el) el.disabled = !editable;
    });
    // The write-only secret box stays disabled until "Replace" is clicked.
    var secret = doc.getElementById('adp-client-secret');
    if (secret) secret.disabled = true;
    var testBtn = doc.getElementById('test-connection');
    if (testBtn) testBtn.disabled = !canTestConnection(role);
    var note = doc.getElementById('conn-role-note');
    if (note) note.hidden = editable;
  }

  var api = {
    ROLE_ADMIN: ROLE_ADMIN,
    ROLE_MANAGER: ROLE_MANAGER,
    ROLE_VIEWER: ROLE_VIEWER,
    ROLE_EXTERNAL: ROLE_EXTERNAL,
    ROLE_SLUGS: [ROLE_ADMIN, ROLE_MANAGER, ROLE_VIEWER, ROLE_EXTERNAL],
    normalizeRoleSlug: normalizeRoleSlug,
    canEditConnection: canEditConnection,
    canTestConnection: canTestConnection,
    CONNECTION_EDIT_IDS: CONNECTION_EDIT_IDS,
    applyConnectionRbac: applyConnectionRbac,
  };

  root.Rbac = api;
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }
})(typeof window !== 'undefined' ? window : globalThis);

#!/usr/bin/env node
// CLI helper: seed / update the *pending* superadmin.
//
// Purpose (per the build request "Optional CLI helper command"):
//   - create a pending admin row (password_setup_required = true) with a random
//     temporary password hash IF no admin exists yet, or
//   - update the pending superadmin's email when a pending admin already exists.
//
// The row is created with role='admin', is_active=true and
// password_setup_required=true so the account cannot log in until the operator
// completes first-time password setup via POST /api/auth/setup/password. Once an
// *active* (non-pending) admin exists, this command refuses to touch it — only
// the POST /api/auth/bootstrap/superadmin flow (or nothing) may create the real
// first admin. This keeps the pending-bootstrap pattern race-safe and matches
// the same NOT EXISTS guard used by the app (src/auth/repo.ts).
//
// Uses only the pg driver + node:crypto (no TS build step needed), mirroring
// scripts/migrate.mjs. Secrets are never printed; the temporary hash is random
// and unusable for login (login is blocked while password_setup_required=true).
//
// Usage:
//   node scripts/bootstrap-superadmin.mjs <email> [tenantId]
//   npm run bootstrap:superadmin -- <email> [tenantId]

import crypto from 'node:crypto';
import pg from 'pg';

const email = (process.argv[2] || '').trim().toLowerCase();
const tenantId = (process.argv[3] || 'default').trim() || 'default';

if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  console.error('usage: node scripts/bootstrap-superadmin.mjs <email> [tenantId]');
  console.error('error: a valid email address is required');
  process.exit(2);
}

const url = process.env.DATABASE_URL || 'postgres://app:app@127.0.0.1:5432/app';

// Build a scrypt hash string in the exact format src/auth/crypto.ts expects
// (scrypt$N$r$p$saltB64$hashB64) from a random, discarded password. The account
// is pending, so this hash is never used to authenticate — it only satisfies the
// NOT NULL password_hash column with a value that cannot be guessed.
function randomTempHash() {
  const N = 16384;
  const r = 8;
  const p = 1;
  const keylen = 32;
  const salt = crypto.randomBytes(16);
  const secret = crypto.randomBytes(32).toString('base64');
  const hash = crypto.scryptSync(secret, salt, keylen, { N, r, p });
  return `scrypt$${N}$${r}$${p}$${salt.toString('base64')}$${hash.toString('base64')}`;
}

const client = new pg.Client({ connectionString: url });
await client.connect();

try {
  await client.query('BEGIN');
  // Lock the users table's admin rows for this tenant so concurrent runs (or a
  // concurrent bootstrap request) serialize on the admin-existence check.
  const existing = await client.query(
    "SELECT id, email, password_setup_required, is_active FROM users WHERE tenant_id = $1 AND role = 'admin' AND email NOT LIKE '%@fixture.invalid' FOR UPDATE",
    [tenantId],
  );

  const admin = existing.rows[0];

  if (!admin) {
    // No admin at all — create a fresh pending superadmin, guarded by NOT EXISTS
    // (matches src/auth/repo.ts createPendingAdmin so only one can win).
    const inserted = await client.query(
      `INSERT INTO users (tenant_id, email, password_hash, password_setup_required, role, is_active, provider)
       SELECT $1, $2, $3, true, 'admin', true, 'builtin'
       WHERE NOT EXISTS (SELECT 1 FROM users WHERE tenant_id = $1 AND role = 'admin' AND email NOT LIKE '%@fixture.invalid')
       RETURNING id, email`,
      [tenantId, email, randomTempHash()],
    );
    if (inserted.rowCount === 0) {
      await client.query('ROLLBACK');
      console.error('error: an admin already exists — refusing to create another');
      process.exit(1);
    }
    await client.query('COMMIT');
    console.log(
      `created pending superadmin id=${inserted.rows[0].id} email=${inserted.rows[0].email} (tenant=${tenantId})`,
    );
    console.log('next: complete first-time setup via POST /api/auth/setup/password');
  } else if (admin.password_setup_required) {
    // A pending admin already exists — update its email (and refresh the temp
    // hash so any previously-known value is invalidated).
    await client.query(
      'UPDATE users SET email = $1, password_hash = $2, password_setup_required = true, is_active = true WHERE id = $3',
      [email, randomTempHash(), admin.id],
    );
    await client.query('COMMIT');
    console.log(
      `updated pending superadmin id=${admin.id} email=${email} (tenant=${tenantId})`,
    );
    console.log('next: complete first-time setup via POST /api/auth/setup/password');
  } else {
    // An active (already set up) admin exists — never overwrite it here.
    await client.query('ROLLBACK');
    console.error('error: an active admin already exists — refusing to modify it');
    process.exit(1);
  }
} catch (err) {
  try {
    await client.query('ROLLBACK');
  } catch {
    /* ignore rollback error */
  }
  console.error('bootstrap-superadmin failed:', err.message);
  process.exit(1);
} finally {
  await client.end();
}

import { Router } from 'express';
import { z } from 'zod';
import { requireRole, getAuth, requestMeta } from './rbac.js';
import { DEFAULT_PERMISSIONS, defaultAllows } from './permissions.js';
import type { Role } from './rbac.js';
import { issueLoginLink, AuthError } from './service.js';
import {
  LdapsSettingsInput,
  LdapsError,
  getLdapsSettings,
  saveLdapsSettings,
  testLdapsSettings,
} from './ldaps-service.js';
import {
  listRoles,
  listOverrides,
  getRole,
  createRole,
  updateRoleLabel,
  deleteRole,
  countUsersWithRole,
  setOverride,
  deleteOverride,
  listLoggedInUsers,
  findUserById,
  setUserRole,
  setUserActive,
  writeAudit,
} from './repo.js';

const router = Router();

// All admin RBAC/user management is admin-only (rule-q28/q38: Admin all).
const adminOnly = requireRole('admin');

const KEY_RE = /^[a-z][a-z0-9_]{1,31}$/;

// POST /admin/users/:id/login-link — one-time sign-in link for the account.
// Send the URL to the user (chat/email/SMS): they click, choose a password,
// and are signed in — no temporary password. Also the manual forgot-password
// path. Raw token returned ONCE; only its hash is stored. Consumed on
// password set (never by link previews); 7-day expiry; reissuing is safe.
router.post('/admin/users/:id/login-link', adminOnly, async (req, res) => {
  try {
    const userId = Number(req.params.id);
    if (!Number.isFinite(userId)) {
      res.status(400).json({ error: 'INVALID_INPUT' });
      return;
    }
    const auth = getAuth(req);
    const out = await issueLoginLink({ userId, createdBy: auth?.userId ?? null });
    await writeAudit({
      actorUserId: auth?.userId ?? null,
      action: 'admin.user.login_link',
      resourceType: 'user',
      resourceId: String(userId),
      metadata: requestMeta(req),
    });
    res.json({ path: out.path, expiresAt: out.expiresAt });
  } catch (err) {
    if (err instanceof AuthError) {
      res.status(err.status).json({ error: err.code, message: err.message });
      return;
    }
    throw err;
  }
});

// GET /admin/permissions — roles + permission matrix with source default|override
router.get('/admin/permissions', adminOnly, async (_req, res) => {
  const [roles, overrides] = await Promise.all([listRoles(), listOverrides()]);
  const overrideMap = new Map(overrides.map((o) => [`${o.role}:${o.permission}`, o.allowed]));
  const permissions = Object.keys(DEFAULT_PERMISSIONS);
  const matrix = roles.map((r) => ({
    role: r.key,
    label: r.label,
    isSystem: r.isSystem,
    isEditable: r.isEditable,
    isDeletable: r.isDeletable,
    permissions: permissions.map((p) => {
      const ov = overrideMap.get(`${r.key}:${p}`);
      const def = defaultAllows(p, r.key as Role);
      return {
        permission: p,
        allowed: ov !== undefined ? ov : def,
        source: ov !== undefined ? ('override' as const) : ('default' as const),
      };
    }),
  }));
  res.json({ permissions, roles: matrix });
});

// PUT /admin/permissions — set/clear an override
router.put('/admin/permissions', adminOnly, async (req, res) => {
  const parsed = z
    .object({
      role: z.string().min(1),
      permission: z.string().min(1),
      allowed: z.boolean(),
    })
    .safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'INVALID_INPUT', issues: parsed.error.issues });
    return;
  }
  const { role, permission, allowed } = parsed.data;
  const roleRow = await getRole(role);
  if (!roleRow) {
    res.status(404).json({ error: 'ROLE_NOT_FOUND' });
    return;
  }
  if (!(permission in DEFAULT_PERMISSIONS)) {
    res.status(400).json({ error: 'UNKNOWN_PERMISSION' });
    return;
  }
  // When the requested value equals the default, delete the override row.
  if (allowed === defaultAllows(permission, role as Role)) {
    await deleteOverride(role, permission);
  } else {
    await setOverride(role, permission, allowed);
  }
  const meta = requestMeta(req);
  await writeAudit({
    actorUserId: getAuth(req).userId ?? null,
    action: 'authz.permission.updated',
    resourceType: 'permission',
    resourceId: `${role}:${permission}`,
    metadata: { allowed, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  res.json({ ok: true });
});

// POST /admin/permissions/roles — create a custom role
router.post('/admin/permissions/roles', adminOnly, async (req, res) => {
  const parsed = z
    .object({ key: z.string().min(1), label: z.string().min(1) })
    .safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'INVALID_INPUT', issues: parsed.error.issues });
    return;
  }
  const key = parsed.data.key.trim().toLowerCase();
  if (!KEY_RE.test(key)) {
    res.status(400).json({ error: 'INVALID_ROLE_KEY' });
    return;
  }
  const created = await createRole({ key, label: parsed.data.label });
  if (!created) {
    res.status(409).json({ error: 'ROLE_EXISTS' });
    return;
  }
  const meta = requestMeta(req);
  await writeAudit({
    actorUserId: getAuth(req).userId ?? null,
    action: 'authz.role.created',
    resourceType: 'role',
    resourceId: key,
    metadata: { label: parsed.data.label, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  res.status(201).json(created);
});

// PATCH /admin/permissions/roles/:key — update label (only if editable)
router.patch('/admin/permissions/roles/:key', adminOnly, async (req, res) => {
  const parsed = z.object({ label: z.string().min(1) }).safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'INVALID_INPUT', issues: parsed.error.issues });
    return;
  }
  const role = await getRole(req.params.key);
  if (!role) {
    res.status(404).json({ error: 'ROLE_NOT_FOUND' });
    return;
  }
  if (!role.isEditable) {
    res.status(403).json({ error: 'ROLE_NOT_EDITABLE' });
    return;
  }
  await updateRoleLabel(role.key, parsed.data.label);
  res.json({ ok: true });
});

// DELETE /admin/permissions/roles/:key
router.delete('/admin/permissions/roles/:key', adminOnly, async (req, res) => {
  const key = req.params.key;
  if (key === 'admin' || key === 'staff') {
    res.status(403).json({ error: 'ROLE_PROTECTED' });
    return;
  }
  const role = await getRole(key);
  if (!role) {
    res.status(404).json({ error: 'ROLE_NOT_FOUND' });
    return;
  }
  if (!role.isDeletable) {
    res.status(403).json({ error: 'ROLE_NOT_DELETABLE' });
    return;
  }
  const assigned = await countUsersWithRole(key);
  if (assigned > 0) {
    res.status(409).json({ error: 'ROLE_IN_USE', assigned });
    return;
  }
  await deleteRole(key);
  const meta = requestMeta(req);
  await writeAudit({
    actorUserId: getAuth(req).userId ?? null,
    action: 'authz.role.deleted',
    resourceType: 'role',
    resourceId: key,
    metadata: { ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  res.json({ ok: true });
});

// ---- Admin users APIs -------------------------------------------------------
// GET /admin/users — list users that have logged in
router.get('/admin/users', adminOnly, async (_req, res) => {
  const rows = await listLoggedInUsers();
  res.json(
    rows.map((u) => ({
      id: u.id,
      email: u.email,
      role: u.role,
      isActive: u.isActive,
      provider: u.provider,
      lastLoginAt: u.lastLoginAt,
    })),
  );
});

// PATCH /admin/users/:id/role — cannot remove your own admin role
router.patch('/admin/users/:id/role', adminOnly, async (req, res) => {
  const parsed = z.object({ role: z.string().min(1) }).safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'INVALID_INPUT', issues: parsed.error.issues });
    return;
  }
  const id = Number(req.params.id);
  const target = await findUserById(id);
  if (!target) {
    res.status(404).json({ error: 'USER_NOT_FOUND' });
    return;
  }
  const role = await getRole(parsed.data.role);
  if (!role) {
    res.status(400).json({ error: 'ROLE_NOT_FOUND' });
    return;
  }
  const self = getAuth(req).userId;
  if (self === id && target.role === 'admin' && parsed.data.role !== 'admin') {
    res.status(409).json({ error: 'CANNOT_REMOVE_OWN_ADMIN' });
    return;
  }
  await setUserRole(id, parsed.data.role);
  const meta = requestMeta(req);
  await writeAudit({
    actorUserId: self ?? null,
    action: 'authz.user.role.updated',
    resourceType: 'user',
    resourceId: String(id),
    metadata: { role: parsed.data.role, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  res.json({ ok: true });
});

// PATCH /admin/users/:id/status — cannot deactivate yourself
router.patch('/admin/users/:id/status', adminOnly, async (req, res) => {
  const parsed = z.object({ isActive: z.boolean() }).safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: 'INVALID_INPUT', issues: parsed.error.issues });
    return;
  }
  const id = Number(req.params.id);
  const target = await findUserById(id);
  if (!target) {
    res.status(404).json({ error: 'USER_NOT_FOUND' });
    return;
  }
  const self = getAuth(req).userId;
  if (self === id && !parsed.data.isActive) {
    res.status(409).json({ error: 'CANNOT_DEACTIVATE_SELF' });
    return;
  }
  await setUserActive(id, parsed.data.isActive);
  const meta = requestMeta(req);
  await writeAudit({
    actorUserId: self ?? null,
    action: 'authz.user.status.updated',
    resourceType: 'user',
    resourceId: String(id),
    metadata: { isActive: parsed.data.isActive, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  res.json({ ok: true });
});

// ---- Admin LDAPS settings APIs (admin-only, constitution §4) ---------------
// CRUD + real service-bind test for the enterprise LDAPS connection. Secrets are
// encrypted at rest (rule-q59) and never returned; the view exposes only whether
// a bind password is stored. rule-q28/q38: connection settings are Admin-only.

// GET /admin/ldaps — current settings (never returns the plaintext password)
router.get('/admin/ldaps', adminOnly, async (_req, res) => {
