import { z } from 'zod';

// Standalone auth configuration. In the original ADP app these keys lived on the
// app-wide `config` object; here they are the auth module's OWN contract so the
// package carries no dependency on any host `config.ts`. The host injects a
// resolved AuthConfig at boot via initAuth({ config }) — either hand-built or
// produced by loadAuthConfigFromEnv().
//
// NOTE: the database connection is NOT part of this config. The Drizzle client is
// injected separately (initAuth({ db })); the standalone CLI/migrations read
// DATABASE_URL from the environment directly.

export const AuthConfigSchema = z.object({
  NODE_ENV: z.string().default('development'),

  // JWT signing secret + token lifetimes. Confirmed defaults: access token 15
  // minutes, refresh token 7 days. The dev-only defaults keep local boot working;
  // production MUST inject real secrets from a secrets manager.
  AUTH_JWT_SECRET: z.string().default('dev-insecure-jwt-secret-change-me'),
  AUTH_MASTER_SECRET: z.string().default('dev-insecure-master-secret-change-me'),
  ACCESS_TOKEN_TTL_SECONDS: z.coerce.number().int().positive().default(15 * 60),
  REFRESH_TOKEN_TTL_SECONDS: z.coerce.number().int().positive().default(7 * 24 * 60 * 60),
  // Concurrent-refresh grace window: a just-rotated token stays acceptable for
  // this many seconds so two near-simultaneous refreshes don't both fail.
  REFRESH_GRACE_SECONDS: z.coerce.number().int().nonnegative().default(30),
  // Idle timeout: a refresh token unused for this long is rejected even if not
  // yet expired. Default equals the refresh TTL (no separate idle limit).
  SESSION_IDLE_SECONDS: z.coerce.number().int().positive().default(7 * 24 * 60 * 60),

  // LDAPS transport selection. The real socket-backed connector (`ldapts`) is
  // wired at boot when this is `ldapts` (the deploy default) via
  // wireLdapsFromConfig(). Tests set it to `fake`/`none` and inject their own
  // in-memory transport, so the live connector is never wired inside tests.
  LDAPS_TRANSPORT: z.enum(['ldapts', 'fake', 'none']).default('ldapts'),

  // SSO-gateway identity-header trust. The x-user-role / x-tenant-id headers may
  // establish identity ONLY when the app sits behind a trusted edge proxy
  // (ProxyPilot) that strips those headers from every inbound CLIENT request
  // before injecting verified ones. DEFAULT-OFF: unless an operator asserts that
  // posture (TRUST_PROXY_AUTH=true), a client-supplied x-user-role grants NOTHING
  // and the request is treated as unauthenticated — closing the spoofed-header
  // bypass on the direct/live path.
  TRUST_PROXY_AUTH: z
    .union([z.boolean(), z.enum(['true', 'false'])])
    .default(false)
    .transform((v) => v === true || v === 'true'),
});

export type AuthConfig = z.infer<typeof AuthConfigSchema>;

// The shape a host may pass to resolveAuthConfig / initAuth: any subset, with the
// rest filled from the defaults above.
export type AuthConfigInput = Partial<Record<keyof AuthConfig, unknown>>;

// Build a fully-resolved AuthConfig from a partial object (defaults applied,
// values validated/coerced). Use this when the host constructs config in code.
export function resolveAuthConfig(input: AuthConfigInput = {}): AuthConfig {
  return AuthConfigSchema.parse(input);
}

// Build an AuthConfig from environment variables (defaults applied). Handy when
// the package is mounted in an app that already drives config from the env.
export function loadAuthConfigFromEnv(env: NodeJS.ProcessEnv = process.env): AuthConfig {
  return AuthConfigSchema.parse({
    NODE_ENV: env.NODE_ENV,
    AUTH_JWT_SECRET: env.AUTH_JWT_SECRET,
    AUTH_MASTER_SECRET: env.AUTH_MASTER_SECRET,
    ACCESS_TOKEN_TTL_SECONDS: env.ACCESS_TOKEN_TTL_SECONDS,
    REFRESH_TOKEN_TTL_SECONDS: env.REFRESH_TOKEN_TTL_SECONDS,
    REFRESH_GRACE_SECONDS: env.REFRESH_GRACE_SECONDS,
    SESSION_IDLE_SECONDS: env.SESSION_IDLE_SECONDS,
    LDAPS_TRANSPORT: env.LDAPS_TRANSPORT,
    TRUST_PROXY_AUTH: env.TRUST_PROXY_AUTH,
  });
}

import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import type { AuthConfig } from './config.js';

// ---------------------------------------------------------------------------
// Dependency-injection context for the reusable auth module.
//
// The original ADP code reached for two app-wide singletons — the Drizzle `db`
// (src/db/index.ts) and the app `config` (src/config.ts) — and called the app's
// profile module directly from the bootstrap flow. To make the module reusable
// WITHOUT rewriting every call site, this file re-exposes `db` and `config` as
// the SAME import names the ported source already uses, but backed by values the
// HOST injects once at boot via initAuth().
//
// The trick: `db` and `config` are Proxies that forward every access to the
// currently-injected instance. So `db.select()...` and `config.AUTH_JWT_SECRET`
// in the ported files work unchanged; they simply resolve against whatever the
// host injected. Accessing either before initAuth() throws a clear error rather
// than failing obscurely later.
// ---------------------------------------------------------------------------

// The injected Drizzle client. Typed loosely (`Record<string, never>` schema) so
// the host can pass a db built with ITS OWN full schema — the auth repo only uses
// the query-builder methods (select/insert/update/delete/execute/transaction),
// never the relational `db.query.*` API, so the schema generic is irrelevant.
export type AuthDb = NodePgDatabase<Record<string, never>>;

export interface SuperadminCreatedInfo {
  tenantId: string;
  email: string;
  userId: number;
}

// Optional lifecycle hooks the host can wire. `onSuperadminCreated` replaces the
// ADP-specific `initProfileFromBootstrap` call: it fires exactly once, after the
// first superadmin row is created, so the host can seed a profile, send a
// welcome, etc. Omitted => no-op (the module is fully functional without it).
// Message shape for the outbound-email hook — matches @proxypilot/email's
// sendEmail() input, so wiring the standard email component is one line.
export interface AuthEmailMessage {
  to: string;
  subject: string;
  text?: string;
  html?: string;
}

export interface AuthHooks {
  onSuperadminCreated?(info: SuperadminCreatedInfo): void | Promise<void>;
  // Outbound email for the external-signup verification flow. Omitted ⇒ no
  // sender is wired and external signups activate immediately (dev-friendly).
  sendEmail?(message: AuthEmailMessage): void | Promise<void | { ok: boolean; error?: string }>;
  // Builds the absolute verification URL for a token (the app knows its base
  // URL). Omitted ⇒ the email carries the token as a code to paste.
  verificationUrl?(token: string): string;
}

interface AuthRuntime {
  db: AuthDb;
  config: AuthConfig;
  hooks: AuthHooks;
}

let runtime: AuthRuntime | null = null;

export interface InitAuthOptions {
  db: AuthDb;
  config: AuthConfig;
  hooks?: AuthHooks;
}

// Inject the host's Drizzle client + resolved config (and optional hooks). Call
// once at application boot, BEFORE mounting the routers / serving requests.
// Idempotent-friendly: calling again replaces the runtime (useful in tests).
export function initAuth(opts: InitAuthOptions): void {
  runtime = { db: opts.db, config: opts.config, hooks: opts.hooks ?? {} };
}

// True once initAuth() has been called.
export function isAuthInitialized(): boolean {
  return runtime !== null;
}

// Reset the injected runtime (test helper).
export function resetAuthContext(): void {
  runtime = null;
}

function requireRuntime(): AuthRuntime {
  if (!runtime) {
    throw new Error(
      '@proxypilot/auth: not initialized — call initAuth({ db, config }) at boot before using the auth module.',
    );
  }
  return runtime;
}

export function getDb(): AuthDb {
  return requireRuntime().db;
}

export function getConfig(): AuthConfig {
  return requireRuntime().config;
}

export function getHooks(): AuthHooks {
  return requireRuntime().hooks;
}

// `db` used by repo.ts exactly as the original `import { db } from '../db/index.js'`.
// Every property access/method call forwards to the injected client.
export const db: AuthDb = new Proxy({} as AuthDb, {
  get(_target, prop, receiver) {
    const real = getDb() as unknown as Record<string | symbol, unknown>;
    const value = Reflect.get(real, prop, receiver);
    return typeof value === 'function' ? (value as (...a: unknown[]) => unknown).bind(real) : value;
  },
});

// `config` used by the ported modules exactly as `import { config } from '../config.js'`.
export const config: AuthConfig = new Proxy({} as AuthConfig, {
  get(_target, prop, receiver) {
    const real = getConfig() as unknown as Record<string | symbol, unknown>;
    return Reflect.get(real, prop, receiver);
  },
});

import crypto from 'node:crypto';

// Cryptographic primitives for the auth module, built on Node's audited built-in
// `crypto` (no third-party deps). Password hashing uses scrypt with strong
// defaults; JWTs are HS256 (HMAC-SHA256) signed; refresh tokens are random and
// only their SHA-256 hash is persisted; connection secrets use AES-256-GCM.

// ---- Password hashing (scrypt) ----------------------------------------------
// Format: scrypt$N$r$p$saltB64$hashB64. scrypt is a strong, memory-hard KDF
// available in the Node standard library (bcrypt/argon2 equivalents require
// native deps we cannot install in the sealed container; scrypt is the secure
// built-in default — assumption documented inline).
const SCRYPT_N = 16384;
const SCRYPT_R = 8;
const SCRYPT_P = 1;
const SCRYPT_KEYLEN = 32;

export function hashPassword(password: string): string {
  const salt = crypto.randomBytes(16);
  const hash = crypto.scryptSync(password, salt, SCRYPT_KEYLEN, {
    N: SCRYPT_N,
    r: SCRYPT_R,
    p: SCRYPT_P,
  });
  return `scrypt$${SCRYPT_N}$${SCRYPT_R}$${SCRYPT_P}$${salt.toString('base64')}$${hash.toString('base64')}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  if (!stored || !stored.startsWith('scrypt$')) return false;
  const parts = stored.split('$');
  if (parts.length !== 6) return false;
  const [, nStr, rStr, pStr, saltB64, hashB64] = parts;
  const N = Number(nStr);
  const r = Number(rStr);
  const p = Number(pStr);
  const salt = Buffer.from(saltB64!, 'base64');
  const expected = Buffer.from(hashB64!, 'base64');
  const actual = crypto.scryptSync(password, salt, expected.length, { N, r, p });
  return actual.length === expected.length && crypto.timingSafeEqual(actual, expected);
}

// ---- JWT (HS256) ------------------------------------------------------------
function b64url(input: Buffer | string): string {
  return Buffer.from(input)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function b64urlJson(obj: unknown): string {
  return b64url(JSON.stringify(obj));
}

export interface AccessTokenClaims {
  sub: number; // user id
  role: string;
  tenantId: string;
  provider: string;
  iat: number;
  exp: number;
}

export function signAccessToken(
  claims: Omit<AccessTokenClaims, 'iat' | 'exp'>,
  secret: string,
  ttlSeconds: number,
  now = Math.floor(Date.now() / 1000),
): string {
  const header = { alg: 'HS256', typ: 'JWT' };
  const payload: AccessTokenClaims = { ...claims, iat: now, exp: now + ttlSeconds };
  const head = b64urlJson(header);
  const body = b64urlJson(payload);
  const sig = b64url(crypto.createHmac('sha256', secret).update(`${head}.${body}`).digest());
  return `${head}.${body}.${sig}`;
}

export function verifyAccessToken(
  token: string,
  secret: string,
  now = Math.floor(Date.now() / 1000),
): AccessTokenClaims | null {
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const [head, body, sig] = parts;
  const expected = b64url(
    crypto.createHmac('sha256', secret).update(`${head}.${body}`).digest(),
  );
  const a = Buffer.from(sig!);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  let claims: AccessTokenClaims;
  try {
    claims = JSON.parse(Buffer.from(body!, 'base64').toString('utf8'));
  } catch {
    return null;
  }
  if (typeof claims.exp !== 'number' || claims.exp < now) return null;
  return claims;
}

// ---- Refresh tokens ---------------------------------------------------------
// The opaque token is random and returned to the client; only its SHA-256 hash
// is ever persisted (so a DB leak cannot reconstruct live sessions).
export function newRefreshToken(): { token: string; hash: string } {
  const token = crypto.randomBytes(32).toString('base64url');
  return { token, hash: hashRefreshToken(token) };
}

export function hashRefreshToken(token: string): string {
  return crypto.createHash('sha256').update(token).digest('hex');
}

// ---- Connection secret encryption (AES-256-GCM) -----------------------------
// Secrets (e.g. an LDAPS bind password) are encrypted at rest as ciphertext +
// nonce; the auth tag is appended to the ciphertext. Key is derived from the
// configured master secret so no key material is stored in the DB.
function encKey(masterSecret: string): Buffer {
  return crypto.createHash('sha256').update(`enc:${masterSecret}`).digest();
}

export function encryptSecret(
  plaintext: string,
  masterSecret: string,
): { ciphertext: string; nonce: string } {
  const nonce = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', encKey(masterSecret), nonce);
  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    ciphertext: Buffer.concat([enc, tag]).toString('base64'),
    nonce: nonce.toString('base64'),
  };
}

export function decryptSecret(
  ciphertext: string,
  nonce: string,
  masterSecret: string,
): string {
  const raw = Buffer.from(ciphertext, 'base64');
  const tag = raw.subarray(raw.length - 16);
  const data = raw.subarray(0, raw.length - 16);
  const decipher = crypto.createDecipheriv(
    'aes-256-gcm',
    encKey(masterSecret),
    Buffer.from(nonce, 'base64'),
  );
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(data), decipher.final()]).toString('utf8');
}

// ---- TOTP scaffold (RFC 6238) -----------------------------------------------
// Future-ready MFA. Generates a base32 secret and verifies a 6-digit code with a
// ±1 step window. Not yet wired into the login flow (scaffold only).
const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

export function generateTotpSecret(bytes = 20): string {
  const buf = crypto.randomBytes(bytes);
  let bits = '';
  for (const byte of buf) bits += byte.toString(2).padStart(8, '0');
  let out = '';
  for (let i = 0; i + 5 <= bits.length; i += 5) {
    out += B32[parseInt(bits.slice(i, i + 5), 2)];
  }
  return out;
}

function base32Decode(secret: string): Buffer {
  const clean = secret.toUpperCase().replace(/=+$/, '');
  let bits = '';
  for (const ch of clean) {
    const idx = B32.indexOf(ch);
    if (idx === -1) continue;
    bits += idx.toString(2).padStart(5, '0');
  }
  const bytes: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) bytes.push(parseInt(bits.slice(i, i + 8), 2));
  return Buffer.from(bytes);
}

export function totpCode(secret: string, step = 30, now = Date.now()): string {
  const counter = Math.floor(now / 1000 / step);
  const buf = Buffer.alloc(8);
  buf.writeBigUInt64BE(BigInt(counter));
  const hmac = crypto.createHmac('sha1', base32Decode(secret)).update(buf).digest();
  const offset = hmac[hmac.length - 1]! & 0xf;
  const code =
    ((hmac[offset]! & 0x7f) << 24) |
    ((hmac[offset + 1]! & 0xff) << 16) |
    ((hmac[offset + 2]! & 0xff) << 8) |
    (hmac[offset + 3]! & 0xff);
  return (code % 1_000_000).toString().padStart(6, '0');
}

export function verifyTotp(secret: string, code: string, now = Date.now()): boolean {
  const step = 30;
  for (const drift of [-1, 0, 1]) {
    if (totpCode(secret, step, now + drift * step * 1000) === code) return true;
  }
  return false;
}

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';
import {
  isExternalSignupEnabled,
  setExternalSignupEnabled,
  signupExternal,
  verifyExternalEmail,
  resendExternalVerification,
  listExternalUsers,
  countExternalUsers,
} from './external.js';
import { writeAudit } from './repo.js';
import { getAuth } from './rbac.js';

// ---- Public router: self-signup for OUTSIDE individuals ---------------------
// Mount next to authRoutes, e.g. app.use('/api/auth', externalAuthRoutes).
// Everything here is public by design (a signer-upper has no session yet) and
// safe when the feature is off: every entry point re-checks the admin toggle.

const publicRouter = Router();

const signupSchema = z.object({
  email: z.string().trim().max(320),
  password: z.string().max(200),
});

// GET /signup/status — drives whether the login page shows a "Create account"
// tab at all.
publicRouter.get('/signup/status', async (_req: Request, res: Response) => {
  res.json({ enabled: await isExternalSignupEnabled() });
});

// POST /signup — create an external account. Response is identical for new and
// already-registered addresses (no account enumeration).
publicRouter.post('/signup', async (req: Request, res: Response) => {
  const parsed = signupSchema.safeParse(req.body ?? {});
  if (!parsed.success) return res.status(400).json({ error: 'email and password are required' });
  const result = await signupExternal(parsed.data);
  if (!result.ok) return res.status(403).json({ error: result.error });
  res.status(202).json({
    ok: true,
    next: result.next,
    message: result.next === 'verify-email'
      ? 'Check your email for a verification link to activate your account.'
      : 'Your account is ready — you can sign in now.',
  });
});

// POST /signup/verify — consume the emailed token; activates the account.
publicRouter.post('/signup/verify', async (req: Request, res: Response) => {
  const token = typeof req.body?.token === 'string' ? req.body.token : '';
  const result = await verifyExternalEmail(token);
  if (!result.ok) return res.status(400).json({ error: result.error });
  res.json({ ok: true, message: 'Email verified — you can sign in now.' });
});

// POST /signup/resend — re-issue the verification email (always ok; 1/min).
publicRouter.post('/signup/resend', async (req: Request, res: Response) => {
  const email = typeof req.body?.email === 'string' ? req.body.email : '';
  if (!(await isExternalSignupEnabled())) return res.status(403).json({ error: 'Self-signup is not enabled.' });
  await resendExternalVerification(email);
  res.json({ ok: true, message: 'If that address has a pending account, a new verification email was sent.' });
});

export default publicRouter;

// ---- Admin router: the on/off switch + the external-accounts roster ---------
// MOUNT BEHIND YOUR ADMIN GUARD, e.g.
//   app.use('/api/admin/external', requirePermission('admin.users'), adminExternalRoutes)

export const adminExternalRoutes = Router();

// GET / — the toggle + a count for the settings card.
adminExternalRoutes.get('/', async (_req: Request, res: Response) => {
  res.json({
    external_signup_enabled: await isExternalSignupEnabled(),
    external_user_count: await countExternalUsers(),
  });
});

// PUT / — flip the toggle (audited).
adminExternalRoutes.put('/', async (req: Request, res: Response) => {
  const enabled = req.body?.enabled;
  if (typeof enabled !== 'boolean') return res.status(400).json({ error: 'enabled must be a boolean' });
  await setExternalSignupEnabled(enabled);
  const auth = getAuth(req);
  await writeAudit({
    action: enabled ? 'auth.external.signup_enabled' : 'auth.external.signup_disabled',
    actorUserId: auth?.userId ?? null,
    resourceType: 'auth_settings',
    resourceId: 'external_signup',
  });
  res.json({ ok: true, external_signup_enabled: enabled });
});

// GET /users — the roster of self-signed-up accounts (internal staff use this
// to find a submitter and pull their documentation).
adminExternalRoutes.get('/users', async (_req: Request, res: Response) => {
  res.json({ users: await listExternalUsers() });
});

import { describe, it, expect } from 'vitest';
import { ownerScopeUserId, canAccessOwnedResource, isExternalAuth, ACCOUNT_TYPE_EXTERNAL, MIN_EXTERNAL_PASSWORD_LENGTH } from './external.js';
import { ROLE_EXTERNAL, ROLE_ADMIN, ROLE_VIEWER, ROLE_SLUGS, normalizeRoleSlug } from './roles.js';
import { roleAllows } from './rbac.js';
import type { AuthContext } from './rbac.js';

// Pure-layer tests for external accounts: the visibility scoping (the point of
// the feature) and the role wiring. Signup/verification flows touch the DB and
// are covered by the host app's integration tests.

const ctx = (over: Partial<AuthContext>): AuthContext => ({
  tenantId: 'default',
  role: ROLE_VIEWER,
  authenticated: true,
  userId: 1,
  ...over,
});

describe('role wiring', () => {
  it('external is a canonical slug, below viewer in privilege', () => {
    expect(ROLE_SLUGS).toContain(ROLE_EXTERNAL);
    expect(normalizeRoleSlug('External')).toBe(ROLE_EXTERNAL);
    // requireRole('viewer') must REJECT an external user…
    expect(roleAllows(ROLE_EXTERNAL, ROLE_VIEWER)).toBe(false);
    // …and every internal role clears the external bar.
    expect(roleAllows(ROLE_VIEWER, ROLE_EXTERNAL)).toBe(true);
    expect(roleAllows(ROLE_ADMIN, ROLE_EXTERNAL)).toBe(true);
  });

  it('unknown role values still normalize to viewer, never to external-with-data or admin', () => {
