import { and, desc, eq, isNull, sql } from 'drizzle-orm';
import type { Request, Response, NextFunction } from 'express';
import { db, getHooks } from './context.js';
import { hashPassword } from './crypto.js';
import { users, authSettings, emailVerifications } from './schema.js';
import { findUserByEmail, writeAudit } from './repo.js';
import { ROLE_EXTERNAL } from './roles.js';
