// External (self-signup) accounts — outside individuals who are NOT in the
// employee directory: a provider submitting licenses to a credentialing
// portal, a vendor uploading documents, etc. LDAPS stays the employee path;
// this is the third-party path, and it is OFF until an admin enables it.
//
// The data-visibility rule this module makes easy to enforce:
//   * an EXTERNAL user sees only their own account and their own rows —
//     ownerScopeUserId(auth) returns their user id; apps add
//     `WHERE owner_user_id = <it>` to every list/read of owner-scoped tables;
//   * an INTERNAL user (admin/manager/viewer) gets null — unrestricted — so
//     employees can open any submitter's account to pull documentation.

export const ACCOUNT_TYPE_INTERNAL = 'internal' as const;
export const ACCOUNT_TYPE_EXTERNAL = 'external' as const;

const VERIFY_TOKEN_TTL_MS = 24 * 60 * 60 * 1000; // 24h
const RESEND_MIN_INTERVAL_MS = 60 * 1000;        // 1/min per account

function sha256(value: string): string {
  return crypto.createHash('sha256').update(value).digest('hex');
}

// ---- the on/off setting (auth_settings.external_signup) --------------------

export async function isExternalSignupEnabled(): Promise<boolean> {
  const rows = await db.select().from(authSettings).where(eq(authSettings.key, 'external_signup')).limit(1);
  const value = rows[0]?.value as { enabled?: unknown } | undefined;
  return value?.enabled === true;
}

export async function setExternalSignupEnabled(enabled: boolean): Promise<void> {
  await db.insert(authSettings)
    .values({ key: 'external_signup', value: { enabled }, updatedAt: new Date() })
    .onConflictDoUpdate({
      target: authSettings.key,
      set: { value: { enabled }, updatedAt: new Date() },
    });
}

// ---- signup / verification --------------------------------------------------

export interface SignupResult {
  ok: boolean;
  // 'verify-email' → an email went out (or the console sink logged it);
  // 'active' → no email sender wired, the account is usable immediately.
  next?: 'verify-email' | 'active';
  error?: string;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export const MIN_EXTERNAL_PASSWORD_LENGTH = 10;

async function issueVerification(userId: number, email: string): Promise<void> {
  const token = crypto.randomBytes(32).toString('base64url');
  await db.insert(emailVerifications).values({
    userId,
    tokenHash: sha256(token),
    expiresAt: new Date(Date.now() + VERIFY_TOKEN_TTL_MS),
  });
  const hooks = getHooks();
  const link = hooks.verificationUrl ? hooks.verificationUrl(token) : null;
  await hooks.sendEmail?.({
    to: email,
    subject: 'Verify your email address',
    text: link
      ? `Welcome! Confirm your email address to activate your account:\n\n${link}\n\nThe link expires in 24 hours. If you didn't sign up, ignore this message.`
      : `Welcome! Enter this verification code on the verification screen to activate your account:\n\n${token}\n\nThe code expires in 24 hours. If you didn't sign up, ignore this message.`,
  });
}

// signupExternal — create an inactive external account and send the
// verification email. When NO sendEmail hook is wired the account activates
// immediately (a dev/internal deployment shouldn't dead-end on a missing
// provider). Existing-address signups return the SAME success shape as new
// ones (no account enumeration) — the existing owner gets nothing.
export async function signupExternal(input: { email: string; password: string }): Promise<SignupResult> {
  if (!(await isExternalSignupEnabled())) {
    return { ok: false, error: 'Self-signup is not enabled on this application.' };
  }
  const email = String(input.email || '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { ok: false, error: 'Enter a valid email address.' };
  const password = String(input.password || '');
  if (password.length < MIN_EXTERNAL_PASSWORD_LENGTH) {
    return { ok: false, error: `Password must be at least ${MIN_EXTERNAL_PASSWORD_LENGTH} characters.` };
  }

  const hasEmailSender = !!getHooks().sendEmail;
  const existing = await findUserByEmail(email);
  if (existing) {
    // Indistinguishable from success — no enumeration oracle.
    return { ok: true, next: hasEmailSender ? 'verify-email' : 'active' };
  }

  const inserted = await db.insert(users).values({
    email,
    passwordHash: hashPassword(password),
    role: ROLE_EXTERNAL,
    accountType: ACCOUNT_TYPE_EXTERNAL,
    provider: 'builtin',
    isActive: !hasEmailSender, // active immediately only when nothing can verify
    ...(hasEmailSender ? {} : { emailVerifiedAt: new Date() }),
  }).returning({ id: users.id });
  const userId = inserted[0]!.id;

  if (hasEmailSender) await issueVerification(userId, email);
  await writeAudit({
    action: 'auth.external.signup',
    actorUserId: userId,
    resourceType: 'user',
    resourceId: String(userId),
    metadata: { email, verified: !hasEmailSender },
  });
  return { ok: true, next: hasEmailSender ? 'verify-email' : 'active' };
}

// verifyExternalEmail — consume a one-shot token; activates the account.
export async function verifyExternalEmail(token: string): Promise<{ ok: boolean; error?: string }> {
  const clean = String(token || '').trim();
  if (!clean) return { ok: false, error: 'Missing verification token.' };
  const rows = await db.select().from(emailVerifications)
    .where(and(eq(emailVerifications.tokenHash, sha256(clean)), isNull(emailVerifications.usedAt)))
    .limit(1);
  const row = rows[0];
  if (!row || row.expiresAt.getTime() < Date.now()) {
    return { ok: false, error: 'This verification link is invalid or has expired — request a new one.' };
  }
  await db.update(emailVerifications).set({ usedAt: new Date() }).where(eq(emailVerifications.id, row.id));
  await db.update(users)
    .set({ isActive: true, emailVerifiedAt: new Date() })
    .where(eq(users.id, row.userId));
  await writeAudit({
    action: 'auth.external.verified',
    actorUserId: row.userId,
    resourceType: 'user',
    resourceId: String(row.userId),
  });
  return { ok: true };
}

// resendExternalVerification — re-issue for an unverified external account.
// Same no-enumeration posture: always returns ok. Rate-limited per account.
export async function resendExternalVerification(email: string): Promise<{ ok: boolean }> {
  const user = await findUserByEmail(String(email || '').trim().toLowerCase());
  if (!user || user.accountType !== ACCOUNT_TYPE_EXTERNAL || user.emailVerifiedAt) return { ok: true };
  const recent = await db.select().from(emailVerifications)
    .where(eq(emailVerifications.userId, user.id))
    .orderBy(desc(emailVerifications.id))
    .limit(1);
  const last = recent[0];
  if (last && Date.now() - last.createdAt.getTime() < RESEND_MIN_INTERVAL_MS) return { ok: true };
  await issueVerification(user.id, user.email);
  return { ok: true };
}

// ---- visibility (the point of account types) --------------------------------

export function isExternalAuth(auth: Pick<AuthContext, 'role'>): boolean {
  return auth.role === ROLE_EXTERNAL;
}

// ownerScopeUserId — THE data-scoping primitive. External identity → its own
// user id (apps filter owner-scoped tables to it); internal identity → null
// (unrestricted: employees may open any submitter's records).
export function ownerScopeUserId(auth: AuthContext): number | null {
  // Defensive: an unauthenticated context scopes to an impossible owner (-1),
  // never to "all" — callers should have gated on auth already.
  if (!auth.authenticated) return -1;
  return isExternalAuth(auth) ? (auth.userId ?? -1) : null;
}

// canAccessOwnedResource — direct check for single-row reads/writes.
export function canAccessOwnedResource(auth: AuthContext, ownerUserId: number | null | undefined): boolean {
  const scope = ownerScopeUserId(auth);
  if (scope === null) return true; // internal
  return ownerUserId != null && Number(ownerUserId) === scope;
}

// requireInternal — Express guard for employee-only surfaces (staff lists,
// admin screens, cross-account reads). Externals get 403.
export function requireInternal(req: Request, res: Response, next: NextFunction): void {
  const auth = getAuth(req);
  if (!auth?.authenticated) {
    res.status(401).json({ error: 'authentication required' });
    return;
  }
  if (isExternalAuth(auth)) {
    res.status(403).json({ error: 'this area is for internal users' });
    return;
  }
  next();
}

// listExternalUsers — the internal-facing roster of self-signed-up accounts.
export async function listExternalUsers(): Promise<Array<{
  id: number; email: string; isActive: boolean; emailVerifiedAt: Date | null; createdAt: Date; lastLoginAt: Date | null;
}>> {
  const rows = await db.select().from(users)
    .where(eq(users.accountType, ACCOUNT_TYPE_EXTERNAL))
    .orderBy(desc(users.createdAt));
  return rows.map((u) => ({
    id: u.id,
    email: u.email,
    isActive: u.isActive,
    emailVerifiedAt: u.emailVerifiedAt ?? null,
    createdAt: u.createdAt,
    lastLoginAt: u.lastLoginAt ?? null,
  }));
}

// countExternalUsers — cheap stat for the admin toggle card.
export async function countExternalUsers(): Promise<number> {
  const rows = await db.select({ n: sql<number>`count(*)` }).from(users)
    .where(eq(users.accountType, ACCOUNT_TYPE_EXTERNAL));
  return Number(rows[0]?.n ?? 0);
}

