// Enterprise LDAPS authentication + admin-settings unit tests (task: successful
// bind, wrong bind password, wrong user password, DNS/connection failure, and
// update-without-password preserving the previous secret). These drive the real
// auth algorithm through an injected fake transport (a native LDAP client can't
// be installed in the sealed container), so behaviour is proven deterministically.

const baseConfig: LdapsSecret = LdapsSecretSchema.parse({
  host: 'ldap.example.com',
  port: 636,
  baseDn: 'dc=example,dc=com',
  bindDn: 'cn=svc,dc=example,dc=com',
  bindPassword: 'service-secret',
  userSearchFilter: '(sAMAccountName=%(user)s)',
  tlsVerify: true,
});

// A configurable fake LDAPS transport. It models a directory with one user and
// the service account, and lets each test simulate wrong bind password, wrong
// user password, or a DNS/connection failure.
function makeFakeClient(opts: {
  serviceBindOk?: boolean;
  connError?: string;
  users?: Record<string, { dn: string; email: string; password: string }>;
}): LdapClient {
  const users = opts.users ?? {
    jdoe: { dn: 'cn=jdoe,dc=example,dc=com', email: 'jdoe@example.com', password: 'user-pass' },
  };
  return {
    async serviceBindAndSearch(config, username) {
      if (opts.connError) throw new Error(opts.connError);
      if (opts.serviceBindOk === false) throw new Error('invalidCredentials (49) — service bind failed');
      // Prove the filter was built from the (escaped) username using the config.
      buildUserFilter(config.userSearchFilter, username);
      const u = users[username.toLowerCase()];
      return u ? { dn: u.dn, email: u.email, username } : null;
    },
    async userBind(_config, dn, password) {
      const found = Object.values(users).find((u) => u.dn === dn);
      return Boolean(found && found.password === password);
    },
  };
}

describe('LDAPS authentication algorithm', () => {
  it('successful bind: service bind -> search -> user bind returns ok + email', async () => {
    const client = makeFakeClient({});
    const r = await ldapAuthenticate(baseConfig, 'jdoe', 'user-pass', client);
    expect(r.ok).toBe(true);
    expect(r.email).toBe('jdoe@example.com');
  });

  it('wrong bind (service) password: service bind failure surfaces via test', async () => {
    const client = makeFakeClient({ serviceBindOk: false });
    const t = await testLdapConnection(baseConfig, client);
    expect(t.ok).toBe(false);
    expect(t.reason).toMatch(/49|service bind failed/i);
  });

  it('wrong user password: service+search ok but user bind fails -> bad_credentials', async () => {
    const client = makeFakeClient({});
    const r = await ldapAuthenticate(baseConfig, 'jdoe', 'WRONG', client);
    expect(r.ok).toBe(false);
    expect(r.reason).toBe('bad_credentials');
  });

  it('user not found in directory -> user_not_found_in_directory', async () => {
    const client = makeFakeClient({});
    const r = await ldapAuthenticate(baseConfig, 'ghost', 'whatever', client);
    expect(r.ok).toBe(false);
    expect(r.reason).toBe('user_not_found_in_directory');
  });

  it('DNS/connection failure: transport throws -> test reports the reason', async () => {
    const client = makeFakeClient({ connError: 'getaddrinfo ENOTFOUND ldap.example.com' });
    const t = await testLdapConnection(baseConfig, client);
    expect(t.ok).toBe(false);
    expect(t.reason).toMatch(/ENOTFOUND/);
  });

  it('not configured (no transport wired) -> ldaps_not_configured, never a silent pass', async () => {
    const r = await ldapAuthenticate(baseConfig, 'jdoe', 'user-pass', null);
    expect(r.ok).toBe(false);
    expect(r.reason).toBe('ldaps_not_configured');
    const t = await testLdapConnection(baseConfig, null);
    expect(t.ok).toBe(false);
    expect(t.reason).toBe('ldaps_not_configured');
  });
});

describe('LDAP filter handling (AD-style + injection safety)', () => {
  it('normalizes AD-style {{username}} to the internal %(user)s placeholder', () => {
    expect(normalizeFilter('(sAMAccountName={{username}})')).toBe('(sAMAccountName=%(user)s)');
    expect(displayFilter('(sAMAccountName=%(user)s)')).toBe('(sAMAccountName={{username}})');
  });
  it('escapes LDAP filter metacharacters to prevent injection', () => {
    expect(escapeLdapFilterValue('a)(uid=*')).toBe('a\\29\\28uid=\\2a');
    expect(buildUserFilter('(sAMAccountName=%(user)s)', '*)(x')).toBe('(sAMAccountName=\\2a\\29\\28x)');
  });
  it('rejects a host containing scheme/metacharacters', () => {
    expect(() => sanitizeHost('ldaps://evil.com/foo')).toThrow(/invalid LDAP host/);
    expect(sanitizeHost('LDAP.Example.COM')).toBe('ldap.example.com');
  });
});

describe('LDAPS settings save behaviour (update without password preserves secret)', () => {
  const existing: LdapsSecret = { ...baseConfig, bindPassword: 'ORIGINAL-SECRET' };

  it('blank bindPassword on update keeps the previously stored password', () => {
    const merged = mergeSecret(
      {
        host: 'ldap.example.com',
        port: 636,
        baseDn: 'dc=example,dc=com',
        bindDn: 'cn=svc,dc=example,dc=com',
        bindPassword: '', // left blank
        userSearchFilter: '(sAMAccountName={{username}})',
        tlsVerify: true,
      },
      existing,
    );
    expect(merged.bindPassword).toBe('ORIGINAL-SECRET');
    // AD-style filter is normalized for storage.
    expect(merged.userSearchFilter).toBe('(sAMAccountName=%(user)s)');
  });

  it('a new bindPassword replaces the stored secret', () => {
    const merged = mergeSecret(
      {
        host: 'ldap.example.com',
        port: 636,
        baseDn: 'dc=example,dc=com',
        bindDn: 'cn=svc,dc=example,dc=com',
        bindPassword: 'NEW-SECRET',
        userSearchFilter: '(sAMAccountName={{username}})',
        tlsVerify: false,
      },
      existing,
    );
    expect(merged.bindPassword).toBe('NEW-SECRET');
    expect(merged.tlsVerify).toBe(false);
  });

  it('requires a password when none is stored and none supplied', () => {
    expect(() =>
      mergeSecret(
        {
          host: 'ldap.example.com',
          port: 636,
          baseDn: 'dc=example,dc=com',
          bindDn: 'cn=svc,dc=example,dc=com',
          bindPassword: '',
          userSearchFilter: '(sAMAccountName={{username}})',
          tlsVerify: true,
        },
        null,
      ),
    ).toThrow(/required/i);
  });
});

describe('LDAPS test message mapping (actionable reasons for the UI)', () => {
