describe('LDAPS CA certificate handling (blank-preserves-existing, like password)', () => {
  const PEM = '-----BEGIN CERTIFICATE-----\nMIIBexisting\n-----END CERTIFICATE-----';
  const existingWithCa: LdapsSecret = LdapsSecretSchema.parse({
    ...baseConfig,
    bindPassword: 'ORIGINAL-SECRET',
    caCertFile: PEM,
  });

  const baseInput = {
    host: 'ldap.example.com',
    port: 636,
    baseDn: 'dc=example,dc=com',
    bindDn: 'cn=svc,dc=example,dc=com',
    bindPassword: '',
    userSearchFilter: '(sAMAccountName={{username}})',
    tlsVerify: true,
  };

  it('blank caCert on update keeps the previously stored certificate', () => {
    const merged = mergeSecret({ ...baseInput }, existingWithCa);
    expect(merged.caCertFile).toBe(PEM);
  });

  it('a new caCert replaces the stored certificate', () => {
    const NEW = '-----BEGIN CERTIFICATE-----\nNEWca\n-----END CERTIFICATE-----';
    const merged = mergeSecret({ ...baseInput, caCert: NEW }, existingWithCa);
    expect(merged.caCertFile).toBe(NEW);
  });

  it('the __CLEAR__ sentinel removes the stored certificate', () => {
    const merged = mergeSecret({ ...baseInput, caCert: '__CLEAR__' }, existingWithCa);
    expect(merged.caCertFile).toBeUndefined();
  });

  it('no caCert and none stored -> undefined (system trust store)', () => {
    const merged = mergeSecret({ ...baseInput }, { ...baseConfig, bindPassword: 'x' });
    expect(merged.caCertFile).toBeUndefined();
  });
});

describe('LDAPS canonical transport reason codes map to actionable messages', () => {
  it('tls_failed -> a certificate/CA hint', () => {
    expect(testMessage(false, 'tls_failed')).toMatch(/TLS|certificate|CA/i);
  });
  it('connection_failed -> a reachability/egress hint', () => {
    expect(testMessage(false, 'connection_failed')).toMatch(/reach|network|egress|host|port/i);
  });
  it('bad_bind_credentials -> a bind DN/password hint', () => {
    expect(testMessage(false, 'bad_bind_credentials')).toMatch(/bind DN|bind password/i);
  });
});

import { z } from 'zod';

// LDAPS adapter. The sealed build container cannot install a native LDAP client,
// so this module owns the *contract*: it validates + sanitizes connection
// config, exposes a pluggable `LdapClient` interface, and implements the auth
// algorithm (service bind -> search -> user bind -> resolve directory email).
// A concrete socket-backed client is injected at deploy time; when none is wired
// the adapter reports "not configured" and login falls back to local only.

export const LdapsSecretSchema = z.object({
  host: z.string().min(1),
  port: z.coerce.number().int().positive().default(636),
  baseDn: z.string().min(1),
  bindDn: z.string().min(1),
  bindPassword: z.string().min(1),
  userSearchFilter: z.string().default('(sAMAccountName=%(user)s)'),
  tlsVerify: z.boolean().default(true),
  caCertFile: z.string().optional(),
});
export type LdapsSecret = z.infer<typeof LdapsSecretSchema>;

export function parseLdapsSecret(json: string): LdapsSecret {
  return LdapsSecretSchema.parse(JSON.parse(json));
}

// Sanitize a hostname: allow only DNS-safe characters, reject anything that
// could smuggle a scheme, port trick, or shell/URL metacharacter.
export function sanitizeHost(host: string): string {
  const h = host.trim().toLowerCase();
  if (!/^[a-z0-9.-]+$/.test(h)) {
    throw new Error('invalid LDAP host');
  }
  return h;
}

// Escape a value before substituting it into an LDAP filter (RFC 4515) to
// prevent LDAP injection. Applied to the user-supplied username.
export function escapeLdapFilterValue(value: string): string {
  return value.replace(/[\\*()\u0000]/g, (ch) => {
    switch (ch) {
      case '\\':
        return '\\5c';
      case '*':
        return '\\2a';
      case '(':
        return '\\28';
      case ')':
        return '\\29';
      case '\u0000':
        return '\\00';
      default:
        return ch;
    }
  });
}

export function buildUserFilter(template: string, user: string): string {
  return template.replace(/%\(user\)s/g, escapeLdapFilterValue(user));
}

export interface LdapSearchResult {
  dn: string;
  email?: string;
  username?: string;
}

// The pluggable transport. A deploy-time implementation performs real LDAPS
// binds/searches; tests inject a fake. Absence of an implementation means LDAPS
// is not configured for this deployment.
export interface LdapClient {
  // Bind with the service account and search for a user; returns the entry or
  // null when not found. Throws on connection/bind failure.
  serviceBindAndSearch(config: LdapsSecret, username: string): Promise<LdapSearchResult | null>;
  // Bind as the resolved user DN with the supplied password to verify it.
  userBind(config: LdapsSecret, dn: string, password: string): Promise<boolean>;
}

let injectedClient: LdapClient | null = null;
export function setLdapClient(client: LdapClient | null): void {
  injectedClient = client;
}
export function getLdapClient(): LdapClient | null {
  return injectedClient;
}

export interface LdapAuthResult {
  ok: boolean;
  email?: string;
  username?: string;
  reason?: string;
}

// Full LDAPS authentication algorithm. Returns { ok, email } on success.
export async function ldapAuthenticate(
  config: LdapsSecret,
  username: string,
  password: string,
  client: LdapClient | null = injectedClient,
): Promise<LdapAuthResult> {
  if (!client) return { ok: false, reason: 'ldaps_not_configured' };
  // Defensive: normalize host / filter before use.
  const safe: LdapsSecret = {
    ...config,
    host: sanitizeHost(config.host),
    userSearchFilter: config.userSearchFilter || '(sAMAccountName=%(user)s)',
  };
  const entry = await client.serviceBindAndSearch(safe, username);
  if (!entry) return { ok: false, reason: 'user_not_found_in_directory' };
  const bound = await client.userBind(safe, entry.dn, password);
  if (!bound) return { ok: false, reason: 'bad_credentials' };
  return {
    ok: true,
    email: entry.email?.toLowerCase(),
    username: entry.username,
  };
}

// "Test connection": verify the service account bind (and that a search runs).
export async function testLdapConnection(
  config: LdapsSecret,
  client: LdapClient | null = injectedClient,
): Promise<{ ok: boolean; reason?: string }> {
  if (!client) return { ok: false, reason: 'ldaps_not_configured' };
  try {
    const safe: LdapsSecret = { ...config, host: sanitizeHost(config.host) };
    // A search with a benign non-matching user still exercises the service bind.
    await client.serviceBindAndSearch(safe, '__connection_test__');
    return { ok: true };
  } catch (err) {
    return { ok: false, reason: (err as Error).message };
  }
}

import { z } from 'zod';
import { config } from './context.js';
import { encryptSecret, decryptSecret } from './crypto.js';
import { getLdapsConnection, upsertLdapsConnection, setConnectionStatus, writeAudit } from './repo.js';
import {
  LdapsSecretSchema,
  parseLdapsSecret,
  testLdapConnection,
  getLdapClient,
  type LdapsSecret,
  type LdapClient,
} from './ldap.js';
import type { RequestMeta } from './service.js';

// LDAPS admin settings service. Owns the admin-managed LDAPS connection: the
// non-secret fields (host, port, baseDn, bindDn, userSearchFilter, tlsVerify)
// plus the encrypted-at-rest secret (bindPassword AND the optional CA
// certificate). Drizzle is the ONLY persistence path (constitution §2) — this
// module never touches the DB directly, it delegates to repo.ts. Secrets are
// encrypted with a key referenced from the platform secrets manager
// (AUTH_MASTER_SECRET), never committed and never logged (rule-q59,
// constitution §5).

// The admin-facing input. bindPassword AND caCert are OPTIONAL on update: when
// omitted or blank, the previously encrypted value is preserved; only a non-empty
// value replaces the stored secret (task: "blank -> keep existing", matching the
// password field). caCert is a PEM the admin may paste to trust a private CA.
export const LdapsSettingsInput = z.object({
  host: z.string().trim().min(1, 'host is required'),
  port: z.coerce.number().int().positive().max(65535).default(636),
  baseDn: z.string().trim().min(1, 'baseDn is required'),
  bindDn: z.string().trim().min(1, 'bindDn is required'),
  // Optional: blank => keep existing (see mergeSecret below).
  bindPassword: z.string().optional(),
  // AD-style filters like (sAMAccountName={{username}}) are supported. The stored
  // form uses the %(user)s placeholder used by the LDAP algorithm; we normalize
  // the {{username}} form to it on save so admins can paste AD documentation.
  userSearchFilter: z.string().trim().min(1).default('(sAMAccountName={{username}})'),
  tlsVerify: z.boolean().default(true),
  // Optional CA certificate (PEM) used to trust the directory's TLS chain when
  // tlsVerify is on. Blank on update preserves the stored value; the sentinel
  // '__CLEAR__' removes it (revert to system trust store).
  caCert: z.string().optional(),
});
export type LdapsSettingsInput = z.infer<typeof LdapsSettingsInput>;

// Sentinel the UI can send to explicitly clear a stored CA certificate (vs. a
// blank field, which PRESERVES the stored value — matching the password field).
export const CLEAR_CA_SENTINEL = '__CLEAR__';

// The admin-facing VIEW — never includes the plaintext bindPassword or the CA
// PEM body. Boolean flags tell the UI whether each is already stored (so it can
// show the field blank with a "leave blank to keep current" hint).
export interface LdapsSettingsView {
  configured: boolean;
  host: string;
  port: number;
  baseDn: string;
  bindDn: string;
  userSearchFilter: string;
  tlsVerify: boolean;
  bindPasswordSet: boolean;
  caCertSet: boolean;
  status: string;
  lastTestedAt: string | null;
}

// Normalize an AD-style {{username}} placeholder to the %(user)s form used by
// buildUserFilter(). Both forms are accepted from the admin; we store one form.
export function normalizeFilter(filter: string): string {
  return filter.replace(/\{\{\s*username\s*\}\}/gi, '%(user)s');
}

// Present the filter back to the admin in the AD-style {{username}} form.
export function displayFilter(filter: string): string {
  return filter.replace(/%\(user\)s/g, '{{username}}');
}

// Decrypt and parse the stored secret, or null when none/undecryptable.
function readStoredSecret(
  conn: { secretCiphertext: string; secretNonce: string } | null,
): LdapsSecret | null {
  if (!conn || !conn.secretCiphertext) return null;
  try {
    return parseLdapsSecret(
      decryptSecret(conn.secretCiphertext, conn.secretNonce, config.AUTH_MASTER_SECRET),
    );
  } catch {
    return null;
  }
}

export async function getLdapsSettings(tenantId = 'default'): Promise<LdapsSettingsView> {
  const conn = await getLdapsConnection(tenantId);
  const stored = readStoredSecret(conn);
  if (!stored) {
    return {
      configured: false,
      host: '',
      port: 636,
      baseDn: '',
      bindDn: '',
      userSearchFilter: '(sAMAccountName={{username}})',
      tlsVerify: true,
      bindPasswordSet: false,
      caCertSet: false,
      status: conn?.status ?? 'unconfigured',
      lastTestedAt: conn?.lastTestedAt ? conn.lastTestedAt.toISOString() : null,
    };
  }
  return {
    configured: true,
    host: stored.host,
    port: stored.port,
    baseDn: stored.baseDn,
    bindDn: stored.bindDn,
    userSearchFilter: displayFilter(stored.userSearchFilter),
    tlsVerify: stored.tlsVerify,
    bindPasswordSet: Boolean(stored.bindPassword),
    caCertSet: Boolean(stored.caCertFile && stored.caCertFile.trim() !== ''),
    status: conn?.status ?? 'unconfigured',
    lastTestedAt: conn?.lastTestedAt ? conn.lastTestedAt.toISOString() : null,
  };
}

// Merge admin input with any existing stored secret. When bindPassword is blank/
// omitted, the previously encrypted password is preserved; only a non-empty value
// replaces it. Throws if no password is provided AND none is stored yet.
//
// The CA certificate follows the SAME blank-preserves-existing rule as the
// password: blank/omitted keeps the stored PEM, a non-empty value replaces it,
// and the CLEAR_CA_SENTINEL explicitly removes it.
export function mergeSecret(
  input: LdapsSettingsInput,
  existing: LdapsSecret | null,
): LdapsSecret {
  const newPassword = (input.bindPassword ?? '').trim();
  const password = newPassword !== '' ? newPassword : existing?.bindPassword ?? '';
  if (password === '') {
    throw new LdapsError(400, 'BIND_PASSWORD_REQUIRED', 'a bind password is required');
  }

  // CA certificate: blank => keep existing; '__CLEAR__' => remove; otherwise set.
  const rawCa = input.caCert ?? '';
  let caCertFile: string | undefined;
  if (rawCa.trim() === CLEAR_CA_SENTINEL) {
    caCertFile = undefined;
  } else if (rawCa.trim() !== '') {
    caCertFile = rawCa;
  } else {
    caCertFile = existing?.caCertFile;
  }

  return LdapsSecretSchema.parse({
    host: input.host,
    port: input.port,
    baseDn: input.baseDn,
    bindDn: input.bindDn,
    bindPassword: password,
    userSearchFilter: normalizeFilter(input.userSearchFilter),
    tlsVerify: input.tlsVerify,
    ...(caCertFile !== undefined ? { caCertFile } : {}),
  });
}

export class LdapsError extends Error {
  constructor(
    public status: number,
    public code: string,
    message?: string,
  ) {
    super(message ?? code);
  }
}

export async function saveLdapsSettings(
  input: LdapsSettingsInput,
  meta: RequestMeta = {},
  actorUserId?: number | null,
  tenantId = 'default',
): Promise<LdapsSettingsView> {
  const conn = await getLdapsConnection(tenantId);
  const existing = readStoredSecret(conn);
  const merged = mergeSecret(input, existing);
  const { ciphertext, nonce } = encryptSecret(JSON.stringify(merged), config.AUTH_MASTER_SECRET);
  await upsertLdapsConnection({
    tenantId,
    label: `${merged.host}:${merged.port}`,
    secretCiphertext: ciphertext,
    secretNonce: nonce,
  });
  await writeAudit({
    tenantId,
    actorUserId: actorUserId ?? null,
    action: 'auth.ldaps.settings.updated',
    resourceType: 'auth_connection',
    resourceId: 'ldaps',
    // NEVER log the plaintext password or the CA PEM body (constitution §5) —
    // only whether each was replaced this save, plus the non-secret fields.
    metadata: {
      host: merged.host,
      port: merged.port,
      baseDn: merged.baseDn,
      bindDn: merged.bindDn,
      tlsVerify: merged.tlsVerify,
      passwordReplaced: Boolean((input.bindPassword ?? '').trim()),
      caCertSet: Boolean(merged.caCertFile && merged.caCertFile.trim() !== ''),
      ...meta,
    },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  return getLdapsSettings(tenantId);
}

// Structured test result: { ok, message } as required by the task. The message
// is a human-readable, actionable reason the UI shows (in red on failure).
export interface LdapsTestResult {
  ok: boolean;
  message: string;
  reason?: string;
}

// Map a raw reason/error into a clear, actionable admin-facing message. Handles
// both the low-level socket/DNS strings (thrown by the fake test transport) and
// the canonical reason codes emitted by the real ldapts transport:
//   tls_failed | connection_failed | bad_bind_credentials.
export function testMessage(ok: boolean, reason?: string): string {
  if (ok) return 'Test succeeded — service account bound and directory search ran.';
  switch (reason) {
    case 'ldaps_not_configured':
      return 'LDAPS is not configured yet — save host, bind DN and bind password first.';
    case 'no_ldaps_transport':
      return 'No LDAPS transport is wired in this environment — settings saved, but a live bind test requires the deployed LDAPS connector.';
    case 'tls_failed':
      return 'TLS failed — the directory certificate could not be verified. Check the CA certificate (PEM), the host name, or turn off TLS verification only for testing.';
    case 'connection_failed':
      return 'Connection failed — could not reach the directory. Check host, port and that the network path/egress to the directory is open.';
    case 'bad_bind_credentials':
      return 'Service bind failed — the bind DN or bind password is wrong.';
    default:
      if (reason && /getaddrinfo|ENOTFOUND|EAI_AGAIN|dns/i.test(reason)) {
        return `Connection failed — host could not be resolved (DNS): ${reason}. Check the host name.`;
      }
      if (reason && /ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENETUNREACH|timeout|connect/i.test(reason)) {
        return `Connection failed — could not reach the server: ${reason}. Check host, port and network/firewall.`;
      }
      if (reason && /invalid.?credentials|bind|49/i.test(reason)) {
        return `Service bind failed — the bind DN or bind password is wrong: ${reason}.`;
      }
      return `Test failed: ${reason ?? 'unknown error'}.`;
  }
}

// Perform a REAL service-account bind test using the configured bindDn/
// bindPassword (task requirement). A concrete LDAPS transport is injected at
// deploy time; when none is wired, the result reports that clearly rather than
// silently passing. Returns the structured { ok, message } result.
export async function testLdapsSettings(
  meta: RequestMeta = {},
  actorUserId?: number | null,
  tenantId = 'default',
  client: LdapClient | null = getLdapClient(),
): Promise<LdapsTestResult> {
  const conn = await getLdapsConnection(tenantId);
  const secret = readStoredSecret(conn);
  if (!secret) {
    const result: LdapsTestResult = {
      ok: false,
      reason: 'ldaps_not_configured',
      message: testMessage(false, 'ldaps_not_configured'),
    };
    await auditTest(result, tenantId, actorUserId, meta);
    return result;
  }
  if (!client) {
    const result: LdapsTestResult = {
      ok: false,
      reason: 'no_ldaps_transport',
      message: testMessage(false, 'no_ldaps_transport'),
    };
    await auditTest(result, tenantId, actorUserId, meta);
    if (conn) await setConnectionStatus(conn.id, 'error', true);
    return result;
  }
  const check = await testLdapConnection(secret, client);
  const result: LdapsTestResult = {
    ok: check.ok,
    reason: check.reason,
    message: testMessage(check.ok, check.reason),
  };
  if (conn) await setConnectionStatus(conn.id, check.ok ? 'connected' : 'error', true);
  await auditTest(result, tenantId, actorUserId, meta);
  return result;
}

async function auditTest(
  result: LdapsTestResult,
  tenantId: string,
  actorUserId: number | null | undefined,
  meta: RequestMeta,
): Promise<void> {
  await writeAudit({
    tenantId,
    actorUserId: actorUserId ?? null,
    action: result.ok ? 'auth.ldaps.test.succeeded' : 'auth.ldaps.test.failed',
    resourceType: 'auth_connection',
    resourceId: 'ldaps',
    metadata: { ok: result.ok, reason: result.reason ?? null, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
}

import { describe, it, expect } from 'vitest';
import {
  mapErrorToReason,
  isTlsError,
  isConnError,
  tlsOptions,
} from './ldapts-client.js';
import { LdapsSecretSchema, type LdapsSecret } from './ldap.js';

// Transport-independent unit tests for the REAL ldapts transport's pure logic:
// error -> canonical reason-code mapping and the CA-trust TLS wiring. These use
// synthetic errors / config only — they NEVER open a socket, so they run (and
// stay green) even when the directory LAN is unavailable. This proves the task's
// "map failures to the existing reason codes — do not invent new ones" contract
// deterministically, without depending on a live bind.

const PEM = '-----BEGIN CERTIFICATE-----\nMIIBfakeCA\n-----END CERTIFICATE-----';

function secret(overrides: Partial<LdapsSecret> = {}): LdapsSecret {
  return LdapsSecretSchema.parse({
    host: 'ldap.corp.example.com',
    port: 636,
    baseDn: 'dc=corp,dc=example,dc=com',
    bindDn: 'cn=svc,dc=corp,dc=example,dc=com',
    bindPassword: 'service-secret',
    userSearchFilter: '(sAMAccountName=%(user)s)',
    tlsVerify: true,
    ...overrides,
  });
}

describe('ldapts transport: error -> canonical reason code mapping', () => {
  it('TLS / certificate failures map to tls_failed', () => {
    expect(mapErrorToReason({ code: 'DEPTH_ZERO_SELF_SIGNED_CERT' })).toBe('tls_failed');
    expect(mapErrorToReason({ code: 'UNABLE_TO_VERIFY_LEAF_SIGNATURE' })).toBe('tls_failed');
    expect(mapErrorToReason(new Error('unable to verify the first certificate'))).toBe('tls_failed');
    expect(isTlsError({ code: 'SELF_SIGNED_CERT_IN_CHAIN' })).toBe(true);
  });

  it('network failures (refused / timeout / unreachable / DNS) map to connection_failed', () => {
    expect(mapErrorToReason({ code: 'ECONNREFUSED' })).toBe('connection_failed');
    expect(mapErrorToReason({ code: 'ETIMEDOUT' })).toBe('connection_failed');
    expect(mapErrorToReason({ code: 'EHOSTUNREACH' })).toBe('connection_failed');
    expect(mapErrorToReason({ code: 'ENOTFOUND' })).toBe('connection_failed');
    expect(mapErrorToReason(new Error('getaddrinfo ENOTFOUND ldap.corp.example.com'))).toBe(
      'connection_failed',
    );
    expect(isConnError({ code: 'ECONNRESET' })).toBe(true);
  });

  it('a rejected service bind (LDAP 49) maps to bad_bind_credentials', () => {
    expect(mapErrorToReason({ code: 49 })).toBe('bad_bind_credentials');
    expect(mapErrorToReason(new Error('invalidCredentials (49)'))).toBe('bad_bind_credentials');
  });

  it('an unknown transport failure fails closed as connection_failed (never a new code)', () => {
    const reason = mapErrorToReason(new Error('something unexpected happened'));
    expect(reason).toBe('connection_failed');
    // The mapping only ever emits the three canonical transport codes.
    expect(['tls_failed', 'connection_failed', 'bad_bind_credentials']).toContain(reason);
  });
});

describe('ldapts transport: CA-trust TLS wiring', () => {
  it('applies the stored CA PEM to the TLS context when tlsVerify is on', () => {
    const opts = tlsOptions(secret({ caCertFile: PEM }));
    expect(opts.rejectUnauthorized).toBe(true);
    expect(opts.ca).toBe(PEM);
    expect(opts.servername).toBe('ldap.corp.example.com');
  });

  it('omits the CA when none is stored (falls back to the system trust store)', () => {
    const opts = tlsOptions(secret());
    expect(opts.rejectUnauthorized).toBe(true);
    expect(opts.ca).toBeUndefined();
  });

  it('does not apply the CA (and does not verify) when tlsVerify is off', () => {
    const opts = tlsOptions(secret({ tlsVerify: false, caCertFile: PEM }));
    expect(opts.rejectUnauthorized).toBe(false);
    expect(opts.ca).toBeUndefined();
  });
});

import tls from 'node:tls';
import net from 'node:net';
import { Client } from 'ldapts';
import {
  buildUserFilter,
  type LdapClient,
  type LdapsSecret,
  type LdapSearchResult,
} from './ldap.js';

// Real LDAPS transport backed by `ldapts` — a pure-TypeScript LDAP client with no
// native bindings (so it installs in the sealed container; pinned to a Node-18
// compatible release). This is the concrete implementation of the pluggable
// `LdapClient` interface; it is injected at boot behind config (see server.ts) so
// tests keep using the in-memory fake and stay transport-independent.
//
// Failures are mapped to the existing reason codes the audit metadata and UI
// already consume — NO new codes are invented:
//   - tls_failed          : TLS handshake / certificate trust failure
//   - connection_failed   : connect refused / timed out / host unreachable / DNS
//   - bad_bind_credentials: the SERVICE-account bind was rejected (LDAP 49)
// User-level outcomes (user_not_found, bad_user_password) are decided by the
// shared algorithm in ldap.ts from the search result / user-bind boolean.

// Connect + operation timeouts so a black-holed route fails fast (task: ~5–10s).
const CONNECT_TIMEOUT_MS = 8000;
const OPERATION_TIMEOUT_MS = 8000;

// LDAP result code 49 == invalidCredentials.
const INVALID_CREDENTIALS = 49;

// The canonical reason codes this transport is allowed to emit. Kept here as the
// single source of truth so no new code can leak into the audit metadata / UI.
export type LdapsTransportReason = 'tls_failed' | 'connection_failed' | 'bad_bind_credentials';

export function isTlsError(err: unknown): boolean {
  const e = err as { code?: string; message?: string };
  const code = e?.code ?? '';
  const msg = e?.message ?? '';
  return (
    /CERT|TLS|SSL|DEPTH_ZERO|SELF_SIGNED|UNABLE_TO_VERIFY|HANDSHAKE/i.test(code) ||
    /certificate|tls|ssl|handshake/i.test(msg)
  );
}

export function isConnError(err: unknown): boolean {
  const e = err as { code?: string; message?: string };
  const code = e?.code ?? '';
  const msg = e?.message ?? '';
  return (
    /ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENETUNREACH|ENOTFOUND|EAI_AGAIN|ECONNRESET|EPIPE/i.test(
      code,
    ) || /timeout|timed out|unreachable|refused|getaddrinfo|connect/i.test(msg)
  );
}

// Translate any transport error into ONE of the existing reason codes. TLS is
// checked first (a cert failure often also looks like a reset at the socket).
// Pure and network-free so it is unit-testable without the directory LAN.
export function mapErrorToReason(err: unknown): LdapsTransportReason {
  if (isTlsError(err)) return 'tls_failed';
  if (isConnError(err)) return 'connection_failed';
  const ldapCode = (err as { code?: number })?.code;
  if (ldapCode === INVALID_CREDENTIALS) return 'bad_bind_credentials';
  if (/invalidCredentials|\(49\)/i.test((err as Error)?.message ?? '')) {
    return 'bad_bind_credentials';
  }
  // Unknown transport failure — surface as a connection problem rather than
  // inventing a new code (fail closed, fail loud).
  return 'connection_failed';
}

function mapError(err: unknown): Error {
  return new Error(mapErrorToReason(err));
}

// Build the ldapts TLS options from the stored secret. When tlsVerify is on and
// a CA PEM was supplied, it is applied to the TLS context so a directory using a
// private CA is trusted without disabling verification. Exported so the CA-trust
// wiring is unit-testable without opening a socket.
export function tlsOptions(
  config: LdapsSecret,
): tls.SecureContextOptions & { rejectUnauthorized: boolean; servername: string } {
  const opts: tls.SecureContextOptions & { rejectUnauthorized: boolean; servername: string } = {
    rejectUnauthorized: config.tlsVerify !== false,
    servername: config.host,
  };
  if (config.tlsVerify !== false && config.caCertFile && config.caCertFile.trim() !== '') {
    opts.ca = config.caCertFile;
  }
  return opts;
}

function makeClient(config: LdapsSecret): Client {
  return new Client({
    url: `ldaps://${config.host}:${config.port}`,
    connectTimeout: CONNECT_TIMEOUT_MS,
    timeout: OPERATION_TIMEOUT_MS,
    tlsOptions: tlsOptions(config),
  });
}

export class LdaptsClient implements LdapClient {
  async serviceBindAndSearch(
    config: LdapsSecret,
    username: string,
  ): Promise<LdapSearchResult | null> {
    const client = makeClient(config);
    try {
      try {
        await client.bind(config.bindDn, config.bindPassword);
      } catch (err) {
        throw mapError(err);
      }
      const filter = buildUserFilter(config.userSearchFilter, username);
      const { searchEntries } = await client.search(config.baseDn, {
        scope: 'sub',
        filter,
        // Pull the attributes we resolve identity from.
        attributes: ['mail', 'userPrincipalName', 'sAMAccountName', 'uid', 'cn'],
        sizeLimit: 2,
      });
      const entry = searchEntries[0];
      if (!entry) return null;
      const email = firstString(entry.mail) ?? firstString(entry.userPrincipalName);
      const resolvedUsername =
        firstString(entry.sAMAccountName) ?? firstString(entry.uid) ?? firstString(entry.cn);
      return {
        dn: entry.dn,
        email,
        username: resolvedUsername,
      };
    } catch (err) {
      // Search/transport failures (already-mapped errors pass through).
      if (err instanceof Error && isMappedReason(err.message)) throw err;
      throw mapError(err);
    } finally {
      await safeUnbind(client);
    }
  }

  async userBind(config: LdapsSecret, dn: string, password: string): Promise<boolean> {
    // An empty password must never bind (some directories treat an empty
    // password bind as an anonymous success) — reject before hitting the wire.
    if (!password) return false;
    const client = makeClient(config);
    try {
      await client.bind(dn, password);
      return true;
    } catch (err) {
      const ldapCode = (err as { code?: number })?.code;
      // A rejected user password is the expected negative outcome -> false, so
      // the shared algorithm maps it to bad_user_password. Anything else (TLS /
      // connection) is a genuine transport failure and must surface.
      if (ldapCode === INVALID_CREDENTIALS || /invalidCredentials|\(49\)/i.test((err as Error)?.message ?? '')) {
        return false;
      }
      if (isTlsError(err) || isConnError(err)) throw mapError(err);
      return false;
    } finally {
      await safeUnbind(client);
    }
  }
}

function isMappedReason(msg: string): boolean {
  return (
    msg === 'tls_failed' ||
    msg === 'connection_failed' ||
    msg === 'bad_bind_credentials'
  );
}

function firstString(v: unknown): string | undefined {
  if (typeof v === 'string') return v;
  if (Array.isArray(v) && typeof v[0] === 'string') return v[0];
  if (Buffer.isBuffer(v)) return v.toString('utf8');
  return undefined;
}

async function safeUnbind(client: Client): Promise<void> {
  try {
    await client.unbind();
  } catch {
    /* best-effort cleanup */
  }
}

// A lightweight TLS reachability probe to the configured host:port, used at boot
// (and available to the test path) to prove the egress route to the directory is
// live BEFORE claiming the transport works. Fails fast; maps to the same reason
// codes. Resolves { ok, reason } — never throws.
export async function probeReachability(
  host: string,
  port: number,
  rejectUnauthorized = false,
  timeoutMs = CONNECT_TIMEOUT_MS,
): Promise<{ ok: boolean; reason?: string; detail?: string }> {
  return new Promise((resolve) => {
    let settled = false;
    const done = (r: { ok: boolean; reason?: string; detail?: string }) => {
      if (settled) return;
      settled = true;
      try {
        socket.destroy();
      } catch {
        /* ignore */
      }
      resolve(r);
    };
    const socket = tls.connect(
      { host, port, servername: host, rejectUnauthorized },
      () => done({ ok: true }),
    );
    socket.setTimeout(timeoutMs, () =>
      done({ ok: false, reason: 'connection_failed', detail: 'TLS connect timed out' }),
    );
    socket.on('error', (err: NodeJS.ErrnoException) => {
      const reason = isTlsError(err) ? 'tls_failed' : 'connection_failed';
      done({ ok: false, reason, detail: `${err.code ?? ''} ${err.message}`.trim() });
    });
  });
}

// Keep `net` import used (avoids an unused-import in strict builds if the socket
// helper above is refactored to net); intentional no-op reference.
void net;

import { ROLE_ADMIN } from './roles.js';
import type { Role } from './rbac.js';

// Default permission map. Effective permission = this map, then a DB override
// row (role_permission_overrides) wins when present.
//
// What ships here is only what the component's OWN admin screens check. The
// keys an application needs are the application's to add — the ADP-specific
// ones this used to ship ('staff.view', 'adp.sync') were an accident of where
// the component was extracted from, and every app inherited them.
//
// DECLARING A PERMISSION IS PART OF ADDING A PERMISSIONED SURFACE. A key that
// is not in this map does not appear in Admin -> Permissions and cannot be
// overridden there (PUT /admin/permissions rejects it as UNKNOWN_PERMISSION),
// so a feature whose permission was never declared can never be granted to a
// manager or a viewer. Add the key alongside the surface:
//
//   'invoices.view': ['viewer', 'manager', 'admin'],
//   'invoices.void': ['admin'],
export const DEFAULT_PERMISSIONS: Record<string, readonly Role[]> = {
  // Operational dashboards — Manager and Admin.
  'admin.dashboard': ['manager', 'admin'],
  // Admin-only surfaces.
  'admin.settings': ['admin'],
  'admin.connections': ['admin'],
  'admin.users': ['admin'],
};

export type PermissionSource = 'default' | 'override';

// Admin holds every permission by default, including one this map has never
// heard of.
//
// Not a convenience: an undeclared key used to deny EVERYONE, so a build that
// added a permissioned surface and forgot to declare it locked the
// administrator out of the app's own feature — and out of the fix, because the
// override screen only offers declared keys. "Admin = all" is the rule the rest
// of this component states; this is where it holds.
//
// Every other role still authorizes purely through the map, so an undeclared
// key stays closed to them, and a deliberate exception for admin remains
// expressible: an explicit override row wins over this (see effectiveAllows).
export function defaultAllows(permission: string, role: Role): boolean {
  const roles = DEFAULT_PERMISSIONS[permission];
  if (!roles) return role === ROLE_ADMIN;
  return roles.includes(role);
}

// Effective decision given the (possibly absent) override row for this
// role+permission. Override always wins over the default map.
export function effectiveAllows(
  permission: string,
  role: Role,
  override: boolean | undefined,
): boolean {
  if (override !== undefined) return override;
  return defaultAllows(permission, role);
}

import { describe, it, expect } from 'vitest';
import { ROLE_ADMIN, ROLE_MANAGER, ROLE_VIEWER, ROLE_SLUGS } from './roles.js';
import { loadRbacShared } from './test-support/load-rbac-shared.js';

// The browser gating (public/rbac-shared.js) MUST use the exact same role slugs
// as the server's canonical set (src/auth/roles.ts). If they ever drift, an
// admin can be locked out of the edit surfaces again (the original defect). This
// test loads the actual shipped front-end module and asserts the values match —
// making "single shared source of truth" a machine-checked property, not a
// comment.
const Rbac = loadRbacShared();

describe('front-end RBAC slugs mirror the server canonical set', () => {
  it('exposes the same admin/manager/viewer slug literals', () => {
    expect(Rbac.ROLE_ADMIN).toBe(ROLE_ADMIN);
    expect(Rbac.ROLE_MANAGER).toBe(ROLE_MANAGER);
    expect(Rbac.ROLE_VIEWER).toBe(ROLE_VIEWER);
  });

  it('exposes the same ordered slug set', () => {
    expect(Rbac.ROLE_SLUGS).toEqual([...ROLE_SLUGS]);
  });

  it('normalises the display label "Administrator" (and case) back to the admin slug', () => {
    expect(Rbac.normalizeRoleSlug('Administrator')).toBe(ROLE_ADMIN);
    expect(Rbac.normalizeRoleSlug('ADMIN')).toBe(ROLE_ADMIN);
    expect(Rbac.normalizeRoleSlug('admin')).toBe(ROLE_ADMIN);
    // Unknown / empty -> least privilege.
    expect(Rbac.normalizeRoleSlug('nonsense')).toBe(ROLE_VIEWER);
