import { describe, it, expect } from 'vitest';
import { roleAllows } from './rbac.js';

// rule-q24: distinct roles (Admin, Manager, Viewer) with separate permissions,
// enforced server-side.
describe('rbac roles (rule-q24)', () => {
  it('admin outranks manager and viewer', () => {
    expect(roleAllows('admin', 'admin')).toBe(true);
    expect(roleAllows('admin', 'manager')).toBe(true);
    expect(roleAllows('admin', 'viewer')).toBe(true);
  });
  it('manager can act as manager and viewer but not admin', () => {
    expect(roleAllows('manager', 'admin')).toBe(false);
    expect(roleAllows('manager', 'manager')).toBe(true);
    expect(roleAllows('manager', 'viewer')).toBe(true);
  });
  it('viewer is least privileged', () => {
    expect(roleAllows('viewer', 'admin')).toBe(false);
    expect(roleAllows('viewer', 'manager')).toBe(false);
    expect(roleAllows('viewer', 'viewer')).toBe(true);
  });
});

// rule-q28 / rule-q38: "Manager: view + trigger sync". Triggering the ADP
// integration (POST /api/adp/test) is guarded by requireRole('manager'), so a
// Manager may trigger it and a Viewer may not — while editing connection
// settings stays admin-only. These assertions lock that confirmed matrix.
