  });
  it('admin may trigger an ADP sync/test', () => {
    expect(roleAllows('admin', triggerSyncRequires)).toBe(true);
  });
  it('viewer may not trigger an ADP sync/test', () => {
    expect(roleAllows('viewer', triggerSyncRequires)).toBe(false);
  });
});

import type { Request, Response, NextFunction } from 'express';
import cookie from 'cookie';
import { config } from './context.js';
import { verifyAccessToken } from './crypto.js';
import { effectiveAllows } from './permissions.js';
import { getOverride, writeAudit } from './repo.js';
import { ROLE_SLUGS, ROLE_VIEWER, normalizeRoleSlug, type RoleSlug } from './roles.js';

// Roles for the application (rule-q24/q37: Admin, Manager, Viewer with separate
// permissions). RBAC is enforced server-side on every protected path
// (constitution §4) — never in the client, never advisory. The role set is
// DB-driven (roles table); this union is the built-in/system baseline used for
// the privilege ranking. Custom roles created via the admin API authorize purely
// through the permission map/overrides.
//
// The canonical slug set lives in ./roles.ts — the SINGLE source of truth shared
// with the browser front-end (public/rbac-shared.js mirrors these exact values,
// asserted equal by a test). `Role` is that slug union.
export type Role = RoleSlug;
export const ROLES: readonly Role[] = ROLE_SLUGS;

// Name of the httpOnly cookie carrying the JWT access token. rule-q50 picks the
// server-side gate model: withAuth validates the access token from this cookie
// so the `/` route can gate the app shell server-side (redirect to /login when
// invalid). The SPA still sends `Authorization: Bearer` on every /api fetch from
// its in-memory copy; the cookie exists so a fresh page GET is also gated.
export const ACCESS_COOKIE = 'access_token';

export interface AuthContext {
  tenantId: string;
  role: Role;
  // Whether an identity was asserted for this request. When false the caller has
  // no session and must be forced to sign in.
  authenticated: boolean;
  // Present when the identity came from a verified JWT access token.
  userId?: number;
  provider?: string;
}

// Normalise any role value (slug or display label, any case) to a canonical
// slug — least privilege (viewer) for anything unrecognised.
function parseRole(value: string | undefined): Role {
  return normalizeRoleSlug(value);
}

function claimsToContext(claims: {
  tenantId: string;
  role: string;
  sub: number;
  provider: string;
}): AuthContext {
  return {
    tenantId: claims.tenantId || 'default',
    role: parseRole(claims.role),
    authenticated: true,
    userId: claims.sub,
    provider: claims.provider,
  };
}

function readAccessCookie(req: Request): string | undefined {
  const header = req.headers.cookie;
  if (!header) return undefined;
  return cookie.parse(header)[ACCESS_COOKIE];
}

// Identity is established ONLY from a verified credential (constitution §4): a
// verified JWT access token presented either as `Authorization: Bearer` (SPA
// /api fetches, per the administrator-approved JWT deviation) or as the httpOnly
// access-token cookie (so a bare page GET of `/` is gated server-side,
// rule-q50).
//
// The pre-built SSO gateway path may ALSO establish identity from an
// x-user-role / x-tenant-id header pair — but §4 is explicit that this is valid
// ONLY because the edge proxy (ProxyPilot) strips those headers from every
// inbound CLIENT request before injecting verified ones. A raw client hitting
// the app directly must NEVER have its x-user-role honoured. We therefore gate
// the header path behind `config.TRUST_PROXY_AUTH` (DEFAULT-OFF): unless an
// operator has asserted the app sits behind that header-stripping trusted proxy,
// a client-supplied x-user-role grants NOTHING and the request is treated as
// unauthenticated (forced to sign in). This closes the spoofed-header bypass on
// the default/live posture, satisfying the §4 negative assertion.
export function withAuth(req: Request, _res: Response, next: NextFunction): void {
  const bearer = (req.header('authorization') || '').replace(/^Bearer\s+/i, '').trim();
  if (bearer) {
    const claims = verifyAccessToken(bearer, config.AUTH_JWT_SECRET);
    if (claims) {
      (req as Request & { auth: AuthContext }).auth = claimsToContext(claims);
      next();
      return;
    }
  }
  const cookieToken = readAccessCookie(req);
  if (cookieToken) {
    const claims = verifyAccessToken(cookieToken, config.AUTH_JWT_SECRET);
    if (claims) {
      (req as Request & { auth: AuthContext }).auth = claimsToContext(claims);
      next();
      return;
    }
  }
  // SSO-gateway header fallback — trusted ONLY when the operator has asserted a
  // header-stripping trusted proxy is in front of the app. Otherwise a raw
  // x-user-role is ignored and the caller is unauthenticated (§4).
  if (config.TRUST_PROXY_AUTH) {
    const assertedRole = (req.header('x-user-role') || '').trim().toLowerCase();
    if (assertedRole !== '') {
      const tenantId = (req.header('x-tenant-id') || '').trim() || 'default';
      (req as Request & { auth: AuthContext }).auth = {
        tenantId,
        role: parseRole(assertedRole),
        authenticated: true,
      };
      next();
      return;
    }
  }
  (req as Request & { auth: AuthContext }).auth = {
    tenantId: 'default',
    role: ROLE_VIEWER,
    authenticated: false,
  };
  next();
}

export function getAuth(req: Request): AuthContext {
  const auth = (req as Request & { auth?: AuthContext }).auth;
  if (!auth) return { tenantId: 'default', role: ROLE_VIEWER, authenticated: false };
  return auth;
}

// True when an identity was asserted for this request.
export function isAuthenticated(req: Request): boolean {
  return getAuth(req).authenticated;
}

// Request metadata attached to authz audit records (constitution §5).
export function requestMeta(req: Request): {
  ip: string;
  userAgent: string;
  route: string;
  method: string;
} {
  return {
    ip: (req.headers['x-forwarded-for'] as string) || req.ip || req.socket.remoteAddress || '',
    userAgent: req.header('user-agent') || '',
    route: req.originalUrl || req.url,
    method: req.method,
  };
}

// Route guard: rejects with 401 server-side when no signed-in identity was
// asserted, so the client is forced to the login flow.
export function requireAuth(req: Request, res: Response, next: NextFunction): void {
  if (!isAuthenticated(req)) {
    res.status(401).json({ error: 'unauthenticated' });
    return;
  }
  next();
}

// A role satisfies a requirement if it is at least as privileged. admin >
// manager > viewer.
const RANK: Record<Role, number> = { admin: 3, manager: 2, viewer: 1, external: 0 };
export function roleAllows(role: Role, required: Role): boolean {
  return RANK[role] >= RANK[required];
}

// Route guard: rejects with 401 when unauthenticated (force login), or 403 when
// the caller's role is below the required level. Audits authz.denied.
export function requireRole(...required: Role[]) {
  return (req: Request, res: Response, next: NextFunction): void => {
    if (!isAuthenticated(req)) {
      res.status(401).json({ error: 'unauthenticated' });
      return;
    }
    const auth = getAuth(req);
    const ok = required.some((r) => roleAllows(auth.role, r));
    if (!ok) {
      void writeAudit({
        tenantId: auth.tenantId,
        actorUserId: auth.userId ?? null,
        action: 'authz.denied',
        metadata: { requiredRole: required, role: auth.role, ...requestMeta(req) },
        ip: requestMeta(req).ip,
        userAgent: requestMeta(req).userAgent,
      });
      res.status(403).json({ error: 'forbidden', requiredRole: required });
      return;
    }
    next();
  };
}

// Route guard: evaluate default permission map + DB override; 403 when denied,
// audit authz.denied. Enforced server-side (constitution §4).
export function requirePermission(permission: string) {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    if (!isAuthenticated(req)) {
      res.status(401).json({ error: 'unauthenticated' });
      return;
    }
    const auth = getAuth(req);
    const override = await getOverride(auth.role, permission);
    if (!effectiveAllows(permission, auth.role, override)) {
      const meta = requestMeta(req);
      void writeAudit({
        tenantId: auth.tenantId,
        actorUserId: auth.userId ?? null,
        action: 'authz.denied',
        resourceType: 'permission',
        resourceId: permission,
        metadata: { role: auth.role, ...meta },
        ip: meta.ip,
        userAgent: meta.userAgent,
      });
      res.status(403).json({ error: 'forbidden', permission });
      return;
    }
    next();
  };
}

import { and, eq, isNull, isNotNull, gt, sql } from 'drizzle-orm';
// `db` is injected by the host at boot via initAuth({ db }); context.ts re-exposes
// it under the same name so this repo's call sites are unchanged.
import { db } from './context.js';
import {
  users,
  roles,
  refreshTokens,
  rolePermissionOverrides,
  authConnections,
  authAuditLog,
} from './schema.js';

// Repositories — the ONLY data-access path for the auth module (Drizzle, §2).

export type UserRow = typeof users.$inferSelect;
export type RoleRow = typeof roles.$inferSelect;

// rule-q53: "first-time" state is defined by ZERO users existing in the
// database (not merely the absence of an admin-role user). The superadmin
// signup is shown only while no user exists at all.
// Accounts on the reserved fixture domain (@fixture.invalid — seeded by the
// build platform's automated UI checks) are NOT real users and never count:
// the first-admin bootstrap stays reserved for the operator even when test
// fixtures exist.
export const FIXTURE_EMAIL_DOMAIN = '@fixture.invalid';

export async function usersExist(tenantId = 'default'): Promise<boolean> {
  const rows = await db
    .select({ id: users.id })
    .from(users)
    .where(and(eq(users.tenantId, tenantId), sql`lower(${users.email}) NOT LIKE ${'%' + FIXTURE_EMAIL_DOMAIN}`))
    .limit(1);
  return rows.length > 0;
}

export async function findUserByEmail(
  email: string,
  tenantId = 'default',
): Promise<UserRow | null> {
  const rows = await db
    .select()
    .from(users)
    .where(and(eq(users.tenantId, tenantId), sql`lower(${users.email}) = lower(${email})`))
    .limit(1);
  return rows[0] ?? null;
}

export async function findUserById(id: number): Promise<UserRow | null> {
  const rows = await db.select().from(users).where(eq(users.id, id)).limit(1);
  return rows[0] ?? null;
}

// Race-safe first-admin creation: a single INSERT guarded by NOT EXISTS in one
// statement, wrapped in a SERIALIZABLE transaction. Only one concurrent caller
// can win; the rest insert zero rows. rule-q53: the guard is "no user exists
// yet" so the definition of first-time state matches bootstrapStatus exactly.
export async function createFirstAdmin(input: {
  email: string;
  passwordHash: string;
  tenantId?: string;
}): Promise<UserRow | null> {
  const tenantId = input.tenantId ?? 'default';
  return db.transaction(async (tx) => {
    const inserted = await tx.execute(sql`
      INSERT INTO users (tenant_id, email, password_hash, password_setup_required, role, is_active, provider, last_login_at)
      SELECT ${tenantId}, ${input.email.toLowerCase()}, ${input.passwordHash}, false, 'admin', true, 'builtin', now()
      WHERE NOT EXISTS (
        SELECT 1 FROM users WHERE tenant_id = ${tenantId} AND lower(email) NOT LIKE ${'%' + FIXTURE_EMAIL_DOMAIN}
      )
      RETURNING *
    `);
    const rows = (inserted as unknown as { rows: UserRow[] }).rows;
    return rows[0] ?? null;
  });
}

// Create a pending admin (passwordSetupRequired=true) if no user exists — used
// by the CLI helper. Race-safe via the same NOT EXISTS guard.
export async function createPendingAdmin(input: {
  email: string;
  tempHash: string;
  tenantId?: string;
}): Promise<UserRow | null> {
  const tenantId = input.tenantId ?? 'default';
  const inserted = await db.execute(sql`
    INSERT INTO users (tenant_id, email, password_hash, password_setup_required, role, is_active, provider)
    SELECT ${tenantId}, ${input.email.toLowerCase()}, ${input.tempHash}, true, 'admin', true, 'builtin'
    WHERE NOT EXISTS (
      SELECT 1 FROM users WHERE tenant_id = ${tenantId} AND lower(email) NOT LIKE ${'%' + FIXTURE_EMAIL_DOMAIN}
    )
    RETURNING *
  `);
  const rows = (inserted as unknown as { rows: UserRow[] }).rows;
  return rows[0] ?? null;
}

export async function setPassword(
  userId: number,
  passwordHash: string,
): Promise<void> {
  await db
    .update(users)
    .set({ passwordHash, passwordSetupRequired: false })
    .where(eq(users.id, userId));
}

// ---- One-time sign-in links (admin-issued setup / password reset) ----------
export type LoginLinkRow = {
  id: number;
  user_id: number;
  token_hash: string;
  expires_at: Date | string;
  completed_at: Date | string | null;
};

export async function createLoginLink(input: {
  userId: number;
  tokenHash: string;
  createdBy?: number | null;
