export async function findLoginLinkByHash(tokenHash: string): Promise<LoginLinkRow | null> {
  const r = await db.execute(sql`
    SELECT id, user_id, token_hash, expires_at, completed_at
    FROM login_links WHERE token_hash = ${tokenHash} LIMIT 1
  `);
