export async function createRole(input: { key: string; label: string }): Promise<RoleRow | null> {
  const inserted = await db.execute(sql`
    INSERT INTO roles (key, label, is_system, is_editable, is_deletable)
    VALUES (${input.key}, ${input.label}, false, true, true)
    ON CONFLICT (key) DO NOTHING
    RETURNING *
  `);
  const rows = (inserted as unknown as { rows: RoleRow[] }).rows;
  return rows[0] ?? null;
}

export async function updateRoleLabel(key: string, label: string): Promise<void> {
  await db.update(roles).set({ label, updatedAt: new Date() }).where(eq(roles.key, key));
}

export async function deleteRole(key: string): Promise<void> {
  await db.delete(roles).where(eq(roles.key, key));
}

export async function countUsersWithRole(role: string): Promise<number> {
  const rows = await db.select({ id: users.id }).from(users).where(eq(users.role, role));
  return rows.length;
}

