// ---- Refresh tokens ---------------------------------------------------------
export async function insertRefreshToken(input: {
  userId: number;
  tokenHash: string;
  expiresAt: Date;
}): Promise<void> {
  await db.insert(refreshTokens).values(input);
}

export async function findRefreshToken(
  tokenHash: string,
): Promise<typeof refreshTokens.$inferSelect | null> {
  const rows = await db
    .select()
    .from(refreshTokens)
    .where(eq(refreshTokens.tokenHash, tokenHash))
    .limit(1);
  return rows[0] ?? null;
}

// Atomically mark a token revoked ONLY if it is currently live (not already
// revoked). Returns true when this call performed the revocation — the winner of
// a concurrent rotation.
export async function revokeIfLive(tokenHash: string): Promise<boolean> {
  const res = await db
    .update(refreshTokens)
    .set({ revokedAt: new Date() })
    .where(and(eq(refreshTokens.tokenHash, tokenHash), isNull(refreshTokens.revokedAt)))
    .returning({ id: refreshTokens.id });
  return res.length > 0;
}

export async function revokeAllForUser(userId: number): Promise<void> {
  await db
    .update(refreshTokens)
    .set({ revokedAt: new Date() })
    .where(and(eq(refreshTokens.userId, userId), isNull(refreshTokens.revokedAt)));
}

// A token revoked within the grace window is still acceptable for rotation once
// (concurrent-refresh race). `now - revokedAt <= grace`.
export async function findRecentlyRevoked(
  tokenHash: string,
  graceSeconds: number,
): Promise<typeof refreshTokens.$inferSelect | null> {
  const cutoff = new Date(Date.now() - graceSeconds * 1000);
  const rows = await db
    .select()
    .from(refreshTokens)
    .where(and(eq(refreshTokens.tokenHash, tokenHash), gt(refreshTokens.revokedAt, cutoff)))
    .limit(1);
  return rows[0] ?? null;
}

// ---- Connections ------------------------------------------------------------
export async function upsertLdapsConnection(input: {
  tenantId?: string;
  label: string;
  secretCiphertext: string;
  secretNonce: string;
}): Promise<void> {
  const tenantId = input.tenantId ?? 'default';
  const existing = await db
    .select()
    .from(authConnections)
    .where(and(eq(authConnections.tenantId, tenantId), eq(authConnections.provider, 'ldaps')))
    .limit(1);
  if (existing[0]) {
    await db
      .update(authConnections)
      .set({
        label: input.label,
        secretCiphertext: input.secretCiphertext,
        secretNonce: input.secretNonce,
        status: 'unconfigured',
        updatedAt: new Date(),
      })
      .where(eq(authConnections.id, existing[0].id));
  } else {
    await db.insert(authConnections).values({
      tenantId,
      provider: 'ldaps',
      label: input.label,
      secretCiphertext: input.secretCiphertext,
      secretNonce: input.secretNonce,
    });
  }
}

export async function getLdapsConnection(
  tenantId = 'default',
): Promise<typeof authConnections.$inferSelect | null> {
  const rows = await db
    .select()
    .from(authConnections)
    .where(and(eq(authConnections.tenantId, tenantId), eq(authConnections.provider, 'ldaps')))
    .limit(1);
  return rows[0] ?? null;
}

export async function setConnectionStatus(
  id: number,
  status: string,
  tested = false,
): Promise<void> {
  await db
    .update(authConnections)
    .set({ status, ...(tested ? { lastTestedAt: new Date() } : {}), updatedAt: new Date() })
    .where(eq(authConnections.id, id));
}

