// Single source of truth for the application's role SLUGS (machine-readable
// identifiers), shared by the server (RBAC guards, /api/profile) and — via
// public/rbac-shared.js, whose values are asserted equal to these by a test —
// the browser front-end's permission gating.
//
// Why this file exists: the "admin cannot type into Connection Settings" defect
// came from the client comparing a role value against a hard-coded 'admin'
// literal while /api/profile handed it the display LABEL ("Administrator"). The
// fix is one canonical slug set that both layers reference, plus a normalizer
// that tolerates case and accidental label/slug mixups, so the two layers can
// never silently disagree about what "admin" is.

export const ROLE_ADMIN = 'admin' as const;
export const ROLE_MANAGER = 'manager' as const;
export const ROLE_VIEWER = 'viewer' as const;
// External (self-signup) accounts — outside individuals (e.g. a provider
// submitting licenses). Below viewer in privilege and scoped to their own
// data — see external.ts ownerScopeUserId().
export const ROLE_EXTERNAL = 'external' as const;

// The built-in/system role slugs, most→least privileged.
export const ROLE_SLUGS = [ROLE_ADMIN, ROLE_MANAGER, ROLE_VIEWER, ROLE_EXTERNAL] as const;
export type RoleSlug = (typeof ROLE_SLUGS)[number];

// Human-friendly display labels shown in the header/profile. The client must
// NEVER gate on these — it gates on the slug — but the normalizer maps them
// back to a slug defensively.
const LABEL_TO_SLUG: Record<string, RoleSlug> = {
  administrator: ROLE_ADMIN,
  admin: ROLE_ADMIN,
  manager: ROLE_MANAGER,
  viewer: ROLE_VIEWER,
  external: ROLE_EXTERNAL,
};

// Normalise any incoming role value (a slug, or a display label, in any case)
// to a canonical slug. Falls back to the least-privileged slug (viewer) so an
// unknown value never grants privilege. This is the single robust check both
// layers use so "Administrator" / "ADMIN" / "admin" all resolve to 'admin'.
export function normalizeRoleSlug(value: string | null | undefined): RoleSlug {
  if (!value) return ROLE_VIEWER;
  const key = value.trim().toLowerCase();
  return LABEL_TO_SLUG[key] ?? ROLE_VIEWER;
}

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';
import cookie from 'cookie';
import { config } from './context.js';
import { requestMeta } from './rbac.js';
import { ACCESS_COOKIE } from './rbac.js';
import {
  AuthError,
  bootstrapStatus,
  bootstrapSuperadmin,
  validateSetupEmail,
  completePasswordSetup,
  login,
  refresh,
  logout,
  loginLinkStatus,
  completeLoginLink,
  type IssuedTokens,
} from './service.js';

const router = Router();

const REFRESH_COOKIE = 'refresh_token';

// Every route validates its input with a Zod schema (constitution §2).
const EmailPassword = z.object({
  email: z.string().email(),
  password: z.string().min(12, 'password must be at least 12 characters'),
});
const EmailOnly = z.object({ email: z.string().email() });

// Set BOTH session cookies (rule-q50 server-side gate + rule-q51 silent
// refresh):
//   - refresh_token: httpOnly, scoped to /api/auth so it is only sent to the
//     refresh/logout endpoints.
//   - access_token: httpOnly, scoped to / so a bare page GET of `/` is gated
//     server-side by withAuth. The SPA also keeps the token in memory and sends
//     it as `Authorization: Bearer` on every /api fetch; the cookie mirrors it
//     purely so the server can gate the app shell.
function setSessionCookies(res: Response, tokens: IssuedTokens): void {
  const refreshMaxAge = Math.max(
    0,
    Math.floor((tokens.refreshExpiresAt.getTime() - Date.now()) / 1000),
  );
  const secure = config.NODE_ENV === 'production';
  res.append(
    'Set-Cookie',
    cookie.serialize(REFRESH_COOKIE, tokens.refreshToken, {
      httpOnly: true,
      secure,
      sameSite: 'strict',
      path: '/api/auth',
      maxAge: refreshMaxAge,
    }),
  );
  res.append(
    'Set-Cookie',
    cookie.serialize(ACCESS_COOKIE, tokens.accessToken, {
      httpOnly: true,
      secure,
      sameSite: 'strict',
      path: '/',
      maxAge: config.ACCESS_TOKEN_TTL_SECONDS,
    }),
  );
}

function clearSessionCookies(res: Response): void {
  const secure = config.NODE_ENV === 'production';
  res.append(
    'Set-Cookie',
    cookie.serialize(REFRESH_COOKIE, '', {
      httpOnly: true,
      secure,
      sameSite: 'strict',
      path: '/api/auth',
      maxAge: 0,
    }),
  );
  res.append(
    'Set-Cookie',
    cookie.serialize(ACCESS_COOKIE, '', {
      httpOnly: true,
      secure,
      sameSite: 'strict',
      path: '/',
      maxAge: 0,
    }),
  );
}

function readRefreshCookie(req: Request): string | undefined {
  const header = req.headers.cookie;
  if (!header) return undefined;
  return cookie.parse(header)[REFRESH_COOKIE];
}

function handleError(res: Response, err: unknown): void {
  if (err instanceof AuthError) {
    res.status(err.status).json({ error: err.code, message: err.message });
    return;
  }
  if (err instanceof z.ZodError) {
    res.status(400).json({ error: 'INVALID_INPUT', issues: err.issues });
    return;
  }
  // eslint-disable-next-line no-console
  console.error('[auth] unexpected error:', err);
  res.status(500).json({ error: 'INTERNAL' });
}

// GET /auth/bootstrap/status
router.get('/auth/bootstrap/status', async (_req, res) => {
  try {
    res.json(await bootstrapStatus());
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/bootstrap/superadmin
router.post('/auth/bootstrap/superadmin', async (req, res) => {
  try {
    const body = EmailPassword.parse(req.body);
    const tokens = await bootstrapSuperadmin(body, requestMeta(req));
    setSessionCookies(res, tokens);
    res.status(201).json({ accessToken: tokens.accessToken, user: tokens.user });
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/setup/validate-email
router.post('/auth/setup/validate-email', async (req, res) => {
  try {
    const { email } = EmailOnly.parse(req.body);
    res.json(await validateSetupEmail(email));
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/setup/password
router.post('/auth/setup/password', async (req, res) => {
  try {
    const body = EmailPassword.parse(req.body);
    await completePasswordSetup(body, requestMeta(req));
    res.status(204).end();
  } catch (err) {
    handleError(res, err);
  }
});

// ---- One-time sign-in links -------------------------------------------------
// GET /auth/link/status — NON-consuming by design: email/SMS link previewers
// prefetch URLs, so nothing changes until the password is actually set.
router.get('/auth/link/status', async (req, res) => {
  try {
    res.json(await loginLinkStatus(String(req.query.token ?? '')));
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/link/complete — the token is the sole credential: sets the chosen
// password (forcing the change by construction) and signs the user in.
router.post('/auth/link/complete', async (req, res) => {
  try {
    const body = z
      .object({ token: z.string().min(10), password: z.string().min(12) })
      .parse(req.body);
    const tokens = await completeLoginLink(body, requestMeta(req));
    setSessionCookies(res, tokens);
    res.json({ accessToken: tokens.accessToken, user: tokens.user });
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/login
router.post('/auth/login', async (req, res) => {
  try {
    const body = z
      .object({ email: z.string().email(), password: z.string().min(1) })
      .parse(req.body);
    const tokens = await login(body, requestMeta(req));
    setSessionCookies(res, tokens);
    res.json({ accessToken: tokens.accessToken, user: tokens.user });
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/refresh
router.post('/auth/refresh', async (req, res) => {
  try {
    const cookieToken = readRefreshCookie(req);
    const bodyToken = z.object({ refreshToken: z.string().optional() }).parse(req.body ?? {}).refreshToken;
    const token = cookieToken ?? bodyToken;
    if (!token) throw new AuthError(401, 'INVALID_REFRESH_TOKEN', 'no refresh token supplied');
    const tokens = await refresh(token, requestMeta(req));
    setSessionCookies(res, tokens);
    res.json({ accessToken: tokens.accessToken, user: tokens.user });
  } catch (err) {
    handleError(res, err);
  }
});

// POST /auth/logout
router.post('/auth/logout', async (req, res) => {
  try {
    const token = readRefreshCookie(req);
    await logout(token, requestMeta(req));
    clearSessionCookies(res);
    res.status(204).end();
  } catch (err) {
    handleError(res, err);
  }
});

export default router;

import {
