// Drizzle schema for the auth/authz module (migration 0005_auth.sql). Drizzle is
// the ONLY data-access path (constitution §2). Roles follow the confirmed
// rules.md set: admin, manager, viewer (rule-q37/q46) — no staff/payroll.

export const roles = pgTable('roles', {
  key: text('key').primaryKey(),
  label: text('label').notNull(),
  isSystem: boolean('is_system').notNull().default(false),
  isEditable: boolean('is_editable').notNull().default(true),
  isDeletable: boolean('is_deletable').notNull().default(true),
