  id: serial('id').primaryKey(),
  tenantId: text('tenant_id').notNull().default('default'),
  email: text('email').notNull(),
  passwordHash: text('password_hash').notNull().default(''),
  passwordSetupRequired: boolean('password_setup_required').notNull().default(false),
  role: text('role').notNull().references(() => roles.key, { onUpdate: 'cascade' }),
  isActive: boolean('is_active').notNull().default(true),
  provider: text('provider').notNull().default('builtin'),
  // internal (employee/operator-created) vs external (self-signed-up) —
  // migration 0002_auth_external.
  accountType: text('account_type').notNull().default('internal'),
  emailVerifiedAt: timestamp('email_verified_at', { withTimezone: true }),
  totpSecret: text('totp_secret'),
  totpEnabled: boolean('totp_enabled').notNull().default(false),
  lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
});

export const refreshTokens = pgTable('refresh_tokens', {
  id: serial('id').primaryKey(),
  userId: integer('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  tokenHash: text('token_hash').notNull().unique(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  revokedAt: timestamp('revoked_at', { withTimezone: true }),
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
});

export const rolePermissionOverrides = pgTable(
  'role_permission_overrides',
  {
    role: text('role')
      .notNull()
      .references(() => roles.key, { onUpdate: 'cascade', onDelete: 'cascade' }),
    permission: text('permission').notNull(),
    allowed: boolean('allowed').notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => ({ pk: primaryKey({ columns: [t.role, t.permission] }) }),
);

export const authConnections = pgTable('auth_connections', {
  id: serial('id').primaryKey(),
  tenantId: text('tenant_id').notNull().default('default'),
  provider: text('provider').notNull(),
