import { config, getHooks } from './context.js';
import {
  hashPassword,
  verifyPassword,
  signAccessToken,
  newRefreshToken,
  hashRefreshToken,
  decryptSecret,
} from './crypto.js';
import {
  usersExist,
  createFirstAdmin,
  findUserByEmail,
  findUserById,
  setPassword,
  createLoginLink,
  findLoginLinkByHash,
  completeLoginLinksForUser,
  touchLastLogin,
  insertRefreshToken,
  findRefreshToken,
  revokeIfLive,
  findRecentlyRevoked,
  getLdapsConnection,
  writeAudit,
  type UserRow,
} from './repo.js';
import { ldapAuthenticate, parseLdapsSecret } from './ldap.js';
import { randomBytes } from 'node:crypto';

// Errors carry an HTTP status + machine code so routes can translate uniformly.
export class AuthError extends Error {
  constructor(
    public status: number,
    public code: string,
    message?: string,
  ) {
    super(message ?? code);
  }
}

export interface RequestMeta {
  ip?: string;
  userAgent?: string;
  route?: string;
  method?: string;
}

export interface IssuedTokens {
  accessToken: string;
  refreshToken: string;
  refreshExpiresAt: Date;
  user: PublicUser;
}

export interface PublicUser {
  id: number;
  email: string;
  role: string;
  isActive: boolean;
  provider: string;
}

export function toPublicUser(u: UserRow): PublicUser {
  return { id: u.id, email: u.email, role: u.role, isActive: u.isActive, provider: u.provider };
}

async function issueTokens(user: UserRow): Promise<IssuedTokens> {
  const accessToken = signAccessToken(
    { sub: user.id, role: user.role, tenantId: user.tenantId, provider: user.provider },
    config.AUTH_JWT_SECRET,
    config.ACCESS_TOKEN_TTL_SECONDS,
  );
  const { token, hash } = newRefreshToken();
  const refreshExpiresAt = new Date(Date.now() + config.REFRESH_TOKEN_TTL_SECONDS * 1000);
  await insertRefreshToken({ userId: user.id, tokenHash: hash, expiresAt: refreshExpiresAt });
  return { accessToken, refreshToken: token, refreshExpiresAt, user: toPublicUser(user) };
}

// ---- Bootstrap --------------------------------------------------------------
// rule-q53: "first-time" state is when ZERO users exist in the database. The
// superadmin signup is shown only then, and that first bootstrap account is an
// Admin. rule-q54: once bootstrap is done, only the normal SSO/LDAPS login is
// shown. Both are driven by canCreateSuperadmin, which flips off as soon as any
// user exists.
export async function bootstrapStatus(tenantId = 'default'): Promise<{ canCreateSuperadmin: boolean }> {
  return { canCreateSuperadmin: !(await usersExist(tenantId)) };
}

export async function bootstrapSuperadmin(
  input: { email: string; password: string },
  meta: RequestMeta = {},
): Promise<IssuedTokens> {
  if (await usersExist()) {
    await writeAudit({
      action: 'auth.bootstrap.superadmin.denied',
      metadata: { reason: 'users_already_exist', email: input.email, ...meta },
      ip: meta.ip,
      userAgent: meta.userAgent,
    });
    throw new AuthError(409, 'ADMIN_ALREADY_EXISTS', 'a superadmin already exists');
  }
  const created = await createFirstAdmin({
    email: input.email,
    passwordHash: hashPassword(input.password),
  });
  if (!created) {
    // Lost the race — another caller created the first user between our check
    // and insert. The NOT EXISTS guard guarantees only one winner.
    await writeAudit({
      action: 'auth.bootstrap.superadmin.denied',
      metadata: { reason: 'lost_race', email: input.email, ...meta },
      ip: meta.ip,
      userAgent: meta.userAgent,
    });
    throw new AuthError(409, 'ADMIN_ALREADY_EXISTS', 'a superadmin already exists');
  }
  // Fire the host's post-bootstrap hook (replaces ADP's initProfileFromBootstrap).
  // The host can seed a profile from created.email, send a welcome, etc. Optional:
  // when no hook is wired this is a no-op and bootstrap still fully succeeds. Any
  // hook error is swallowed so a host-side side-effect can never fail the
  // superadmin creation itself (the account already exists at this point).
  try {
    await getHooks().onSuperadminCreated?.({
      tenantId: created.tenantId,
      email: created.email,
      userId: created.id,
    });
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error('[auth] onSuperadminCreated hook failed (bootstrap still succeeded):', err);
  }
  const tokens = await issueTokens(created);
  await writeAudit({
    actorUserId: created.id,
    action: 'auth.bootstrap.superadmin.created',
    resourceType: 'user',
    resourceId: String(created.id),
    metadata: { email: created.email, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  return tokens;
}

// ---- First-time password setup ---------------------------------------------
export async function validateSetupEmail(email: string): Promise<{ requiresPasswordSetup: boolean }> {
  const user = await findUserByEmail(email);
  return { requiresPasswordSetup: Boolean(user?.passwordSetupRequired) };
}

export async function completePasswordSetup(
  input: { email: string; password: string },
  meta: RequestMeta = {},
): Promise<void> {
  const user = await findUserByEmail(input.email);
  if (!user || !user.isActive || !user.passwordSetupRequired) {
    throw new AuthError(404, 'NOT_FOUND', 'no pending password setup for this account');
  }
  await setPassword(user.id, hashPassword(input.password));
  await writeAudit({
    actorUserId: user.id,
    action: 'auth.password.setup.completed',
    resourceType: 'user',
    resourceId: String(user.id),
    metadata: { email: user.email, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
}

// ---- One-time sign-in links -------------------------------------------------
// Admin-issued: send the URL to the user (chat/email/SMS); they click, choose
// a password, and are signed in — no temporary password ever exists. Also the
// manual "forgot password" path (issue a new link; the old password keeps
// working until the link is used). The raw token is returned ONCE; only its
// sha256 is stored.
export async function issueLoginLink(input: {
  userId: number;
  createdBy?: number | null;
  ttlHours?: number;
}): Promise<{ token: string; path: string; expiresAt: Date }> {
  const user = await findUserById(input.userId);
  if (!user || !user.isActive) throw new AuthError(404, 'NOT_FOUND', 'no such active user');
  const token = randomBytes(32).toString('base64url');
  const expiresAt = new Date(Date.now() + (input.ttlHours ?? 24 * 7) * 3600 * 1000);
  await createLoginLink({
    userId: user.id,
    tokenHash: hashRefreshToken(token),
    createdBy: input.createdBy ?? null,
    expiresAt,
  });
  await writeAudit({
    actorUserId: input.createdBy ?? null,
    action: 'auth.login_link.issued',
    resourceType: 'user',
    resourceId: String(user.id),
    metadata: { email: user.email },
  });
  return { token, path: `/login#link=${token}`, expiresAt };
}

function maskEmail(email: string): string {
  const [local, domain] = String(email).split('@');
  if (!domain) return '\u2022\u2022\u2022';
  return `${local.slice(0, 2)}${'\u2022'.repeat(Math.max(1, local.length - 2))}@${domain}`;
}

async function findValidLoginLink(token: string): Promise<{ linkUserId: number; user: UserRow } | null> {
  if (!token) return null;
  const link = await findLoginLinkByHash(hashRefreshToken(token));
  if (!link || link.completed_at) return null;
  if (new Date(link.expires_at).getTime() < Date.now()) return null;
  const user = await findUserById(link.user_id);
  if (!user || !user.isActive) return null;
  return { linkUserId: link.user_id, user };
}

// Non-consuming status — GETs must be side-effect free because email/SMS link
// previewers prefetch URLs. The link is spent only when the password is set.
export async function loginLinkStatus(token: string): Promise<{ valid: boolean; email?: string }> {
  const hit = await findValidLoginLink(String(token || ''));
  return hit ? { valid: true, email: maskEmail(hit.user.email) } : { valid: false };
}

// Complete: the token is the sole credential — set the chosen password (this
// clears password_setup_required), void every open link for the user, sign in.
export async function completeLoginLink(
  input: { token: string; password: string },
  meta: RequestMeta = {},
): Promise<IssuedTokens> {
  const hit = await findValidLoginLink(String(input.token || ''));
  if (!hit) throw new AuthError(404, 'NOT_FOUND', 'this sign-in link is no longer valid');
  await setPassword(hit.user.id, hashPassword(input.password));
  await completeLoginLinksForUser(hit.user.id);
  await writeAudit({
    actorUserId: hit.user.id,
    action: 'auth.login_link.completed',
    resourceType: 'user',
    resourceId: String(hit.user.id),
    metadata: { email: hit.user.email, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  const fresh = await findUserById(hit.user.id);
  return issueTokens(fresh ?? hit.user);
}

// ---- Login (local first, LDAPS fallback) ------------------------------------
export async function login(
  input: { email: string; password: string },
  meta: RequestMeta = {},
): Promise<IssuedTokens> {
  const user = await findUserByEmail(input.email);

  // Gate checks that apply to a known local user before anything else.
  if (user) {
    if (!user.isActive) {
      await auditLoginFailure(input.email, 'builtin', 'ACCOUNT_DEACTIVATED', meta, user.id);
      throw new AuthError(403, 'ACCOUNT_DEACTIVATED', 'account is deactivated');
    }
    if (user.passwordSetupRequired) {
      await auditLoginFailure(input.email, 'builtin', 'PASSWORD_SETUP_REQUIRED', meta, user.id);
      throw new AuthError(403, 'PASSWORD_SETUP_REQUIRED', 'password setup required');
    }
    // Primary: local password verification.
    if (user.passwordHash && verifyPassword(input.password, user.passwordHash)) {
      return succeed(user, 'builtin', meta);
    }
  }

  // Fallback: LDAPS, only when a connection is configured. The LDAPS reason is
  // captured so a failed login records `ldapsReason` in its audit metadata
  // (task requirement) without ever logging the supplied password.
  let ldapsReason: string | undefined;
  const conn = await getLdapsConnection();
  if (conn && conn.secretCiphertext) {
    let ldapResult;
    try {
      const secret = parseLdapsSecret(
        decryptSecret(conn.secretCiphertext, conn.secretNonce, config.AUTH_MASTER_SECRET),
      );
      ldapResult = await ldapAuthenticate(secret, input.email, input.password);
    } catch {
      ldapResult = { ok: false as const, reason: 'ldaps_error' };
    }
    ldapsReason = ldapResult.reason;
    if (ldapResult.ok) {
      const directoryEmail = (ldapResult.email || input.email).toLowerCase();
      // rule-q39/q48: NO auto-provisioning. An LDAPS-authenticated user with no
      // local account is rejected — they must be invited by an Admin first.
      const local = user ?? (await findUserByEmail(directoryEmail));
      if (!local) {
        await auditLoginFailure(input.email, 'ldaps', 'ACCOUNT_NOT_FOUND', meta);
        throw new AuthError(
          403,
          'ACCOUNT_NOT_FOUND',
          'Account not found — contact your administrator',
        );
      }
      if (!local.isActive) {
        await auditLoginFailure(local.email, 'ldaps', 'ACCOUNT_DEACTIVATED', meta, local.id);
        throw new AuthError(403, 'ACCOUNT_DEACTIVATED', 'account is deactivated');
      }
      return succeed(local, 'ldaps', meta);
    }
  }

  await auditLoginFailure(
    input.email,
    ldapsReason ? 'ldaps' : user ? 'builtin' : 'unknown',
    'BAD_CREDENTIALS',
    meta,
    user?.id,
    ldapsReason,
  );
  throw new AuthError(401, 'BAD_CREDENTIALS', 'invalid email or password');
}

async function succeed(user: UserRow, provider: string, meta: RequestMeta): Promise<IssuedTokens> {
  await touchLastLogin(user.id);
  const tokens = await issueTokens(user);
  await writeAudit({
    actorUserId: user.id,
    action: 'auth.login.succeeded',
    resourceType: 'user',
    resourceId: String(user.id),
    metadata: { email: user.email, provider, ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  return tokens;
}

async function auditLoginFailure(
  email: string,
  provider: string,
  reason: string,
  meta: RequestMeta,
  actorUserId?: number,
  ldapsReason?: string,
): Promise<void> {
  await writeAudit({
    actorUserId: actorUserId ?? null,
    action: 'auth.login.failed',
    metadata: {
      email,
      provider,
      reason,
      ...(ldapsReason ? { ldapsReason } : {}),
      ...meta,
    },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
}

// ---- Refresh (rotate + revoke, concurrent-race grace) -----------------------
export async function refresh(
  refreshTokenValue: string,
  meta: RequestMeta = {},
): Promise<IssuedTokens> {
  const hash = hashRefreshToken(refreshTokenValue);
  const record = await findRefreshToken(hash);
  if (!record) {
    throw new AuthError(401, 'INVALID_REFRESH_TOKEN', 'refresh token not recognized');
  }
  const now = Date.now();
  // Expiry + idle enforcement.
  if (record.expiresAt.getTime() < now) {
    throw new AuthError(401, 'REFRESH_TOKEN_EXPIRED', 'refresh token expired');
  }
  const idleCutoff = record.createdAt.getTime() + config.SESSION_IDLE_SECONDS * 1000;
  if (idleCutoff < now) {
    throw new AuthError(401, 'SESSION_IDLE_TIMEOUT', 'session idle timeout');
  }

  // Atomically revoke; the winner rotates. A loser that already-revoked within
  // the grace window is still allowed to rotate once (concurrent refresh).
  const won = await revokeIfLive(hash);
  if (!won) {
    const recent = await findRecentlyRevoked(hash, config.REFRESH_GRACE_SECONDS);
    if (!recent) {
      throw new AuthError(401, 'REFRESH_TOKEN_REVOKED', 'refresh token was revoked');
    }
  }

  const user = await findUserById(record.userId);
  if (!user || !user.isActive) {
    throw new AuthError(403, 'ACCOUNT_DEACTIVATED', 'account is deactivated');
  }
  const tokens = await issueTokens(user);
  await writeAudit({
    actorUserId: user.id,
    action: 'auth.token.refreshed',
    resourceType: 'user',
    resourceId: String(user.id),
    metadata: { ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
  return tokens;
}

// ---- Logout -----------------------------------------------------------------
export async function logout(
  refreshTokenValue: string | undefined,
  meta: RequestMeta = {},
  actorUserId?: number,
): Promise<void> {
  if (refreshTokenValue) {
    await revokeIfLive(hashRefreshToken(refreshTokenValue));
  }
  await writeAudit({
    actorUserId: actorUserId ?? null,
    action: 'auth.logout',
    metadata: { ...meta },
    ip: meta.ip,
    userAgent: meta.userAgent,
  });
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Load the REAL shipped browser module public/rbac-shared.js and return its
// exported API. The project is an ESM package, so a plain require()/import of a
// classic-script .js file fails; instead we evaluate the actual file contents in
// a controlled scope with a fake `window` and `module`, exactly the two globals
// the file's UMD wrapper assigns to. This means the tests exercise the same file
// the browser ships — no duplicated logic to drift.
//
// `applyConnectionRbac` takes a DOM `Document`; typed here as a minimal
// getElementById-capable object so this helper needs no DOM lib and stays
// build-clean under NodeNext.
interface MinimalDoc {
  getElementById(id: string): { disabled?: boolean; hidden?: boolean } | null;
}

export interface RbacApi {
  ROLE_ADMIN: string;
  ROLE_MANAGER: string;
  ROLE_VIEWER: string;
  ROLE_SLUGS: string[];
  normalizeRoleSlug(value: unknown): string;
  canEditConnection(role: unknown): boolean;
  canTestConnection(role: unknown): boolean;
  CONNECTION_EDIT_IDS: string[];
  applyConnectionRbac(doc: MinimalDoc, role: unknown): void;
}

export function loadRbacShared(): RbacApi {
  const __dirname = path.dirname(fileURLToPath(import.meta.url));
  const file = path.resolve(__dirname, '../../../public/rbac-shared.js');
  const src = fs.readFileSync(file, 'utf8');
  const moduleObj: { exports: unknown } = { exports: {} };
  const win: Record<string, unknown> = {};
  const fn = new Function('window', 'module', 'globalThis', src);
  fn(win, moduleObj, win);
  return (moduleObj.exports || win.Rbac) as RbacApi;
}

// Minimal ambient types for the `cookie` package (no bundled types in 0.7.x,
// and some sealed build containers cannot fetch @types/cookie). Covers only what
// the auth routes/middleware use: parse + serialize.
declare module 'cookie' {
  export interface CookieSerializeOptions {
    maxAge?: number;
    path?: string;
    domain?: string;
    httpOnly?: boolean;
    secure?: boolean;
    sameSite?: 'strict' | 'lax' | 'none' | boolean;
    expires?: Date;
  }
  export function parse(str: string): Record<string, string | undefined>;
  export function serialize(
    name: string,
    value: string,
    options?: CookieSerializeOptions,
  ): string;
  const _default: { parse: typeof parse; serialize: typeof serialize };
  export default _default;
}

import { getConfig } from './context.js';
import { setLdapClient } from './ldap.js';
import { LdaptsClient, probeReachability } from './ldapts-client.js';
import { getLdapsConnection } from './repo.js';
import { decryptSecret } from './crypto.js';
import { parseLdapsSecret } from './ldap.js';

// Boot-time LDAPS transport wiring, extracted from the original ADP server.ts.
// Call AFTER initAuth(). When config.LDAPS_TRANSPORT === 'ldapts' (the deploy
// default) this injects the real socket-backed `ldapts` client; for 'fake'/'none'
// nothing is wired, so tests inject their own in-memory transport via
// setLdapClient() and stay transport-independent.
//
// When `probe` is true and an LDAPS connection is already configured, it also runs
// a fast TLS reachability probe to the directory host:port at boot and logs the
// outcome — so a black-holed egress route surfaces in startup logs rather than
// only on the first "Test connection". The probe never blocks or fails boot.
export async function wireLdapsFromConfig(opts: { probe?: boolean } = {}): Promise<void> {
  const config = getConfig();
  if (config.LDAPS_TRANSPORT !== 'ldapts') {
    // eslint-disable-next-line no-console
    console.log(`LDAPS transport: ${config.LDAPS_TRANSPORT} (no real client wired)`);
    return;
  }

  setLdapClient(new LdaptsClient());
  // eslint-disable-next-line no-console
  console.log('LDAPS transport: ldapts (real socket-backed client) wired');

  if (!opts.probe) return;
  try {
    const conn = await getLdapsConnection();
    if (!conn || !conn.secretCiphertext) return;
    const secret = parseLdapsSecret(
      decryptSecret(conn.secretCiphertext, conn.secretNonce, config.AUTH_MASTER_SECRET),
    );
    const result = await probeReachability(secret.host, secret.port, secret.tlsVerify !== false);
    if (result.ok) {
      // eslint-disable-next-line no-console
      console.log(`LDAPS reachability probe: ${secret.host}:${secret.port} reachable`);
    } else {
      // eslint-disable-next-line no-console
      console.warn(
        `LDAPS reachability probe FAILED (${result.reason}) for ${secret.host}:${secret.port}: ${result.detail ?? ''} — check the egress grant to the directory host.`,
      );
    }
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(`LDAPS reachability probe error: ${(err as Error).message}`);
  }
}

import type { NextFunction, Request, Response } from 'express';
import { bootstrapStatus } from './service.js';

// bootstrapGate — the FORCING half of the first-admin bootstrap.
//
// The sign-in page's create-administrator form is an affordance; this gate is
// the guarantee. While ZERO users exist the application is uninitialized, and
// the gate makes that state impossible to miss or code around:
//
//   - every browser navigation (a GET that accepts text/html) is redirected to
//     the sign-in page, which shows the create-administrator form;
//   - every API call is refused with 503 BOOTSTRAP_REQUIRED — except the
//     endpoints the bootstrap itself needs (bootstrap status/create, login,
//     first-time password setup, token refresh/logout);
//   - static assets still load, so the sign-in page renders.
//
// Once the first superadmin exists the gate settles into a cached no-op — no
// per-request DB cost for the life of the process.
//
// Mount it ONCE, after withAuth and before your routes and static serving:
//
//   app.use(bootstrapGate());
//
// Do NOT remove this or re-implement a first-run flow of your own: any custom
// login/landing screen you build is still forced through the bootstrap while
// the app is uninitialized, and released automatically the moment the first
// administrator exists.

export interface BootstrapGateOptions {
  /** Where browser navigations are sent while uninitialized (default '/login'). */
  loginPath?: string;
  /** Extra path prefixes to allow through while uninitialized (e.g. '/healthz'). */
  allowPaths?: string[];
  /** Status probe — injectable for tests; defaults to the live bootstrapStatus. */
  status?: () => Promise<{ canCreateSuperadmin: boolean }>;
}

// API endpoints the bootstrap flow itself needs while the app is uninitialized.
// login + setup/* stay open so a CLI-seeded pending superadmin can complete
// first-time password setup; refresh/logout are harmless and keep clients sane.
const BOOTSTRAP_API_ALLOW = [
  '/api/auth/bootstrap/status',
  '/api/auth/bootstrap/superadmin',
  '/api/auth/login',
  '/api/auth/logout',
  '/api/auth/refresh',
  '/api/auth/setup/validate-email',
  '/api/auth/setup/password',
];

export function bootstrapGate(options: BootstrapGateOptions = {}) {
  const loginPath = options.loginPath ?? '/login';
  const allowPaths = options.allowPaths ?? [];
  const status = options.status ?? bootstrapStatus;

  // Settles true forever once a user exists — the common case costs nothing.
  let initialized = false;

  return async function bootstrapGateMiddleware(req: Request, res: Response, next: NextFunction) {
    if (initialized) return next();

    // ALREADY SIGNED IN → through, whatever the bootstrap state says.
    //
    // This gate exists to force first-run setup on an ANONYMOUS visitor. A
    // request carrying a valid session is, by the gate's own definition, not
    // that: someone is using the application. Blocking it produced an app whose
    // pages rendered and whose every API call answered 503, which is a worse
    // failure than the one the gate prevents — and it is exactly what the
    // platform's fixture reviewer hit on a build nobody had signed up to yet.
    // withAuth runs before this middleware and always attaches the context.
    const auth = (req as Request & { auth?: { authenticated?: boolean } }).auth;
    if (auth?.authenticated === true) return next();

    let canCreateSuperadmin = false;
    try {
      ({ canCreateSuperadmin } = await status());
    } catch {
      // Status probe failed (e.g. DB briefly down) — do not lock the app out.
      return next();
    }
    if (!canCreateSuperadmin) {
      initialized = true;
      return next();
    }

    const path = req.path || '/';

    // The bootstrap's own API surface, plus operator-allowed extras.
    if (BOOTSTRAP_API_ALLOW.includes(path) || allowPaths.some((p) => path.startsWith(p))) {
      return next();
    }

    // Any other API call is refused loudly — an uninitialized app must not
    // half-work behind a custom UI.
    if (path.startsWith('/api/')) {
      return res.status(503).json({
        error: 'BOOTSTRAP_REQUIRED',
        message: 'No administrator account exists yet. Create the first administrator to initialize the application.',
        bootstrap: { status: '/api/auth/bootstrap/status', create: '/api/auth/bootstrap/superadmin' },
      });
    }

    // Browser navigations are forced to the sign-in page (which shows the
    // create-administrator form while bootstrap is open). Static assets
    // (scripts, styles, images — requests that don't accept text/html) pass so
    // the page can render.
    const acceptsHtml = String(req.headers.accept || '').includes('text/html');
    if (req.method === 'GET' && acceptsHtml && path !== loginPath && path !== '/login.html') {
      return res.redirect(302, loginPath);
    }

    return next();
  };
}

import { describe, expect, it } from 'vitest';
import { bootstrapGate } from './bootstrap-gate.js';

// Pure unit tests — the status probe is injected, so no DB/context is needed.

type Probe = () => Promise<{ canCreateSuperadmin: boolean }>;

function fakeReq(path: string, { method = 'GET', accept = 'text/html' } = {}) {
  return { path, method, headers: { accept } } as never;
}

function fakeRes() {
  const out: { status?: number; json?: unknown; redirect?: [number, string] } = {};
  const res = {
    status(code: number) { out.status = code; return res; },
    json(body: unknown) { out.json = body; return res; },
    redirect(code: number, url: string) { out.redirect = [code, url]; return res; },
  };
  return { res: res as never, out };
}

async function run(gate: ReturnType<typeof bootstrapGate>, path: string, opts?: { method?: string; accept?: string }) {
  const { res, out } = fakeRes();
  let nexted = false;
  await gate(fakeReq(path, opts), res, () => { nexted = true; });
  return { out, nexted };
}

const OPEN: Probe = async () => ({ canCreateSuperadmin: true });
const CLOSED: Probe = async () => ({ canCreateSuperadmin: false });

describe('bootstrapGate — forcing the first-admin flow', () => {
  it('redirects browser navigations to the sign-in page while uninitialized', async () => {
    const gate = bootstrapGate({ status: OPEN });
    const home = await run(gate, '/');
    expect(home.out.redirect).toEqual([302, '/login']);
    const deep = await run(gate, '/dashboard');
    expect(deep.out.redirect).toEqual([302, '/login']);
  });

  it('lets the sign-in page and its assets through', async () => {
    const gate = bootstrapGate({ status: OPEN });
    expect((await run(gate, '/login')).nexted).toBe(true);
    expect((await run(gate, '/login.html')).nexted).toBe(true);
    // scripts/styles do not accept text/html — they must load
    expect((await run(gate, '/login.js', { accept: '*/*' })).nexted).toBe(true);
    expect((await run(gate, '/app.css', { accept: 'text/css,*/*;q=0.1' })).nexted).toBe(true);
  });

  it('refuses non-bootstrap API calls with 503 BOOTSTRAP_REQUIRED', async () => {
    const gate = bootstrapGate({ status: OPEN });
    const { out } = await run(gate, '/api/anything/else', { method: 'POST', accept: 'application/json' });
    expect(out.status).toBe(503);
    expect((out.json as { error: string }).error).toBe('BOOTSTRAP_REQUIRED');
  });

  it('keeps the bootstrap/login/setup endpoints open', async () => {
    const gate = bootstrapGate({ status: OPEN });
    for (const p of [
      '/api/auth/bootstrap/status', '/api/auth/bootstrap/superadmin',
      '/api/auth/login', '/api/auth/setup/validate-email', '/api/auth/setup/password',
    ]) {
      expect((await run(gate, p, { method: 'POST', accept: 'application/json' })).nexted).toBe(true);
    }
  });

  it('honors extra allowPaths (e.g. health checks)', async () => {
    const gate = bootstrapGate({ status: OPEN, allowPaths: ['/healthz'] });
    expect((await run(gate, '/healthz', { accept: 'application/json' })).nexted).toBe(true);
  });

  it('settles into a no-op once initialized — the probe is never called again', async () => {
    let calls = 0;
    const gate = bootstrapGate({ status: async () => { calls += 1; return { canCreateSuperadmin: false }; } });
    expect((await run(gate, '/')).nexted).toBe(true);
    expect((await run(gate, '/api/things')).nexted).toBe(true);
    expect((await run(gate, '/dashboard')).nexted).toBe(true);
    expect(calls).toBe(1);
  });

  it('flips open→settled the moment the first admin exists', async () => {
    let open = true;
    const gate = bootstrapGate({ status: async () => ({ canCreateSuperadmin: open }) });
    expect((await run(gate, '/')).out.redirect).toEqual([302, '/login']);
    open = false; // superadmin created
    expect((await run(gate, '/')).nexted).toBe(true);
  });

  it('fails open if the status probe throws (DB briefly down must not lock the app)', async () => {
    const gate = bootstrapGate({ status: async () => { throw new Error('db down'); } });
    expect((await run(gate, '/')).nexted).toBe(true);
  });

  it('never touches the DB probe result for CLOSED apps beyond the first request', async () => {
    const gate = bootstrapGate({ status: CLOSED });
    expect((await run(gate, '/api/x')).nexted).toBe(true);
  });
});
